(300879,33431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lába sosem fáj, de tegnap este ... nagyon. Katasztrófa!'::text,'fájt'::text,'fáj'::text,NULL::text,'A lába sosem fáj, de tegnap este fájt nagyon. Katasztrófa!'::text),
(300882,33432,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er meinte, sein Schienbein ... gerade so richtig weh.'::text,'tut'::text,'tun'::text,'tut'::text,'Bestie, er meinte, sein Schienbein tut gerade so richtig weh.'::text),
(300886,33432,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, він сказав, що гомілка в нього саме зараз ... дуже сильно.'::text,'болить'::text,'болять'::text,'болить'::text,'Подружко, він сказав, що гомілка в нього саме зараз болить дуже сильно.'::text),
(300885,33432,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dijo que la espinilla le ... muchísimo ahora mismo.'::text,'está doliendo'::text,'están doliendo'::text,'doliendo'::text,'Amiga, dijo que la espinilla le está doliendo muchísimo ahora mismo.'::text),
(300884,33432,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma chérie, il a dit que son tibia lui ... très mal en ce moment.'::text,'fait'::text,'font'::text,'faisant'::text,'Ma chérie, il a dit que son tibia lui fait très mal en ce moment.'::text),
(300887,33432,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, dediğine göre kaval kemiği şu an çok ...'::text,'ağrıyor'::text,'ağrıyorlar'::text,'ağrıyarak'::text,'Kankam, dediğine göre kaval kemiği şu an çok ağrıyor.'::text),
(300888,33432,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barátnőm, azt mondta, most nagyon ... a sípcsontja.'::text,'fáj'::text,'fájnak'::text,'fájó'::text,'Barátnőm, azt mondta, most nagyon fáj a sípcsontja.'::text),
(300891,33433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich tun ihm die Beine nie weh, aber heute ... ihm das Schienbein richtig weh.'::text,'tut'::text,'tut'::text,NULL::text,'Mädel, angeblich tun ihm die Beine nie weh, aber heute tut ihm das Schienbein richtig weh.'::text),
(300895,33433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ноги в нього ніколи не болять, але сьогодні гомілка ... дуже.'::text,'болить'::text,'болить'::text,NULL::text,'Подруго, кажуть, ноги в нього ніколи не болять, але сьогодні гомілка болить дуже.'::text),
(300894,33433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dicen que nunca le duelen las piernas, pero hoy la espinilla le ... un montón.'::text,'está doliendo'::text,'duele'::text,NULL::text,'Tía, dicen que nunca le duelen las piernas, pero hoy la espinilla le está doliendo un montón.'::text),
(300893,33433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment ses jambes ne lui font jamais mal, mais aujourd''hui son tibia lui ... très mal.'::text,'fait'::text,'fait'::text,NULL::text,'Ma belle, apparemment ses jambes ne lui font jamais mal, mais aujourd''hui son tibia lui fait très mal.'::text),
(300896,33433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya bacakları hiç ağrımazmış ama bugün kaval kemiği çok ...'::text,'ağrıyor'::text,'ağrır'::text,NULL::text,'Kızım, güya bacakları hiç ağrımazmış ama bugün kaval kemiği çok ağrıyor.'::text),
(300897,33433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag sosem fáj a lába, de ma nagyon ... a sípcsontja.'::text,'fáj'::text,'fáj'::text,NULL::text,'Csajszi, állítólag sosem fáj a lába, de ma nagyon fáj a sípcsontja.'::text),
(300900,33434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sein Teamkollege hat mir gesagt, dass das Eis eine Sekunde lang ...'::text,'wehtun wird'::text,'wehtut'::text,'wehtuend'::text,'Hör zu, sein Teamkollege hat mir gesagt, dass das Eis eine Sekunde lang wehtun wird.'::text),
(300904,33434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, його товариш по команді сказав мені, що лід ... на секунду.'::text,'болітиме'::text,'болить'::text,'болячи'::text,'Слухай, його товариш по команді сказав мені, що лід болітиме на секунду.'::text),
(300903,33434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, su compañero de equipo me dijo que el hielo ... un segundo.'::text,'dolerá'::text,'duele'::text,'doliendo'::text,'Oye, su compañero de equipo me dijo que el hielo dolerá un segundo.'::text),
(300902,33434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, son coéquipier m''a dit que la glace ... mal une seconde.'::text,'fera'::text,'fait'::text,'faisant'::text,'Écoute, son coéquipier m''a dit que la glace fera mal une seconde.'::text),
(300905,33434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, takım arkadaşı bana şöyle dedi: buz bir saniye ...'::text,'acıtacak'::text,'acıtır'::text,'acıtarak'::text,'Dinle, takım arkadaşı bana şöyle dedi: buz bir saniye acıtacak.'::text),
(300906,33434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a csapattársa azt mondta, hogy a jég egy pillanatig ...'::text,'fájni fog'::text,'fáj'::text,'fájó'::text,'Figyelj, a csapattársa azt mondta, hogy a jég egy pillanatig fájni fog.'::text),
(300909,33435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dir diesen lila Fleck an. Der ... tagelang wehtun.'::text,'wird'::text,'wird'::text,'wird'::text,'Schau dir diesen lila Fleck an. Der wird tagelang wehtun.'::text),
(300913,33435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подивись на ту фіолетову пляму. Вона ... кілька днів.'::text,'збирається боліти'::text,'збирається боліти'::text,'збирається боліти'::text,'Подивись на ту фіолетову пляму. Вона збирається боліти кілька днів.'::text),
(300912,33435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira esa marca morada. ... durante días.'::text,'Va a doler'::text,'Va a doler'::text,'Va a doler'::text,'Mira esa marca morada. Va a doler durante días.'::text),
(300911,33435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde cette marque violette. Elle ... mal pendant des jours.'::text,'va faire'::text,'va faire'::text,'va faire'::text,'Regarde cette marque violette. Elle va faire mal pendant des jours.'::text),
(300914,33435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu mor ize bak. Günlerce ...'::text,'acıyacak'::text,'acıyacak'::text,'acıyacak'::text,'Şu mor ize bak. Günlerce acıyacak.'::text),
(300915,33435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd azt a lila foltot. Napokig ...'::text,'fájni fog'::text,'fájni fog'::text,'fájni fog'::text,'Nézd azt a lila foltot. Napokig fájni fog.'::text),
(300918,33436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Teamkollege sagt: Ich glaube, das Eis ... bald weniger wehtun.'::text,'wird'::text,'wird'::text,NULL::text,'Sein Teamkollege sagt: Ich glaube, das Eis wird bald weniger wehtun.'::text),
(300922,33436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його товариш по команді каже: думаю, лід скоро ... менше.'::text,'болітиме'::text,'збирається боліти'::text,NULL::text,'Його товариш по команді каже: думаю, лід скоро болітиме менше.'::text),
(300921,33436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero dice: creo que el hielo pronto ... menos.'::text,'dolerá'::text,'va a doler'::text,NULL::text,'Su compañero dice: creo que el hielo pronto dolerá menos.'::text),
(300920,33436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son coéquipier dit : je pense que la glace ... bientôt moins mal.'::text,'fera'::text,'va faire'::text,NULL::text,'Son coéquipier dit : je pense que la glace fera bientôt moins mal.'::text),
(300923,33436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım arkadaşı diyor ki: Bence buz yakında daha az ...'::text,'acıtacak'::text,'acıtacak'::text,NULL::text,'Takım arkadaşı diyor ki: Bence buz yakında daha az acıtacak.'::text),
(300924,33436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapattársa azt mondja: szerintem a jég hamarosan kevésbé ...'::text,'fog fájni'::text,'fog fájni'::text,NULL::text,'A csapattársa azt mondja: szerintem a jég hamarosan kevésbé fog fájni.'::text),
(300927,33437,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es tut weh, aber er schreit: Ich ... das Finale spielen!'::text,'muss'::text,'muss'::text,'darf nicht'::text,'Es tut weh, aber er schreit: Ich muss das Finale spielen!'::text),
(300931,33437,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Болить, але він кричить: я ... грати у фіналі!'::text,'мушу'::text,'маю'::text,'не смію'::text,'Болить, але він кричить: я мушу грати у фіналі!'::text),
(300930,33437,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duele, pero grita: ¡... jugar la final!'::text,'Debo'::text,'Tengo que'::text,'No debo'::text,'Duele, pero grita: ¡Debo jugar la final!'::text),
(300929,33437,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait mal, mais il crie : je ... jouer la finale !'::text,'dois'::text,'dois'::text,'ne dois pas'::text,'Ça fait mal, mais il crie : je dois jouer la finale !'::text),
(300932,33437,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Acıyor ama bağırıyor: Finalde ...!'::text,'oynamalıyım'::text,'oynamak zorundayım'::text,'oynamamalıyım'::text,'Acıyor ama bağırıyor: Finalde oynamalıyım!'::text),
(300933,33437,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fáj, de azt kiabálja: ... játszanom a döntőben!'::text,'kell'::text,'kell'::text,'nem szabad'::text,'Fáj, de azt kiabálja: kell játszanom a döntőben!'::text),
(305526,33948,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Glasturm ... sehr modern.'::text,'ist'::text,'sind'::text,'bin'::text,'Der Glasturm ist sehr modern.'::text),
(305530,33948,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Скляна вежа ... дуже сучасна.'::text,'є'::text,'є'::text,'є'::text,'Скляна вежа є дуже сучасна.'::text),
(305529,33948,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La torre de cristal ... muy moderna.'::text,'es'::text,'son'::text,'soy'::text,'La torre de cristal es muy moderna.'::text),
(305528,33948,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour de verre ... très moderne.'::text,'est'::text,'sont'::text,'suis'::text,'La tour de verre est très moderne.'::text),
(305531,33948,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cam kule çok modern ...'::text,''::text,NULL::text,NULL::text,'Cam kule çok modern.'::text),
(305532,33948,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üvegtorony ... nagyon modern.'::text,''::text,NULL::text,'vagyok'::text,'Az üvegtorony nagyon modern.'::text),
(305535,33949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... zum modernen Glasturm hinauf.'::text,'schaut'::text,'schauen'::text,'schauend'::text,'Er schaut zum modernen Glasturm hinauf.'::text),
(305539,33949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вгору на сучасну скляну вежу.'::text,'дивиться'::text,'дивитися'::text,'дивлячись'::text,'Він дивиться вгору на сучасну скляну вежу.'::text),
(305538,33949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... hacia arriba, a la moderna torre de cristal.'::text,'mira'::text,'mirar'::text,'mirando'::text,'Él mira hacia arriba, a la moderna torre de cristal.'::text),
(305537,33949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... vers la tour de verre moderne.'::text,'lève les yeux'::text,'lever les yeux'::text,'levant les yeux'::text,'Il lève les yeux vers la tour de verre moderne.'::text),
(305540,33949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Modern cam kuleye yukarı doğru ...'::text,'bakar'::text,'bakmak'::text,'bakarak'::text,'Modern cam kuleye yukarı doğru bakar.'::text),
(305541,33949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a modern üvegtoronyra.'::text,'felnéz'::text,'felnézni'::text,'felnéző'::text,'Ő felnéz a modern üvegtoronyra.'::text),
(305544,33950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den modernen Turm von der Straße aus sehen.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann den modernen Turm von der Straße aus sehen.'::text),
(305548,33950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... бачити сучасну вежу з вулиці.'::text,'може'::text,'може'::text,'може'::text,'Він може бачити сучасну вежу з вулиці.'::text),
(305547,33950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde la calle ... ver la torre moderna.'::text,'puede'::text,'puede'::text,'puede'::text,'Desde la calle puede ver la torre moderna.'::text),
(305546,33950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... voir la tour moderne depuis la rue.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut voir la tour moderne depuis la rue.'::text),
(305549,33950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Modern kuleyi sokaktan ...'::text,'görebilir'::text,'görebilir'::text,'görebilir'::text,'Modern kuleyi sokaktan görebilir.'::text),
(305550,33950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcáról ... látni a modern tornyot.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'Az utcáról tudja látni a modern tornyot.'::text),
(305562,33952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... einen modernen Turm neben seinen alten Block! Katastrophe!'::text,'bauten'::text,'bauten'::text,'bauen'::text,'Sie bauten einen modernen Turm neben seinen alten Block! Katastrophe!'::text),
(305566,33952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... сучасну вежу поруч із його старим будинком! Катастрофа!'::text,'збудували'::text,'збудували'::text,'будують'::text,'Вони збудували сучасну вежу поруч із його старим будинком! Катастрофа!'::text),
(305565,33952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... una torre moderna al lado de su viejo bloque! ¡Desastre!'::text,'Construyeron'::text,'Construyeron'::text,'Construyen'::text,'¡Construyeron una torre moderna al lado de su viejo bloque! ¡Desastre!'::text),
(305564,33952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... une tour moderne à côté de son vieil immeuble ! Catastrophe !'::text,'ont construit'::text,'ont construit'::text,'construisent'::text,'Ils ont construit une tour moderne à côté de son vieil immeuble ! Catastrophe !'::text),
(305567,33952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun eski blokunun yanına modern bir kule ...! Felaket!'::text,'diktiler'::text,'diktiler'::text,'dikerler'::text,'Onun eski blokunun yanına modern bir kule diktiler! Felaket!'::text),
(305568,33952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Modern tornyot ... a régi háza mellé! Katasztrófa!'::text,'építettek'::text,'építettek'::text,'építenek'::text,'Modern tornyot építettek a régi háza mellé! Katasztrófa!'::text),
(305571,33953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist das Ende! Der Turm ist ... als sein Block!'::text,'moderner'::text,'moderner'::text,'am modernsten'::text,'Das ist das Ende! Der Turm ist moderner als sein Block!'::text),
(305575,33953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це кінець! Вежа ... за його будинок!'::text,'більш сучасна'::text,'сучасніша'::text,'найсучасніша'::text,'Це кінець! Вежа більш сучасна за його будинок!'::text),
(305574,33953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es el fin! ¡La torre es ... que su bloque!'::text,'más moderna'::text,'más moderna'::text,'la más moderna'::text,'¡Es el fin! ¡La torre es más moderna que su bloque!'::text),
(305573,33953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est la fin ! La tour est ... que son immeuble !'::text,'plus moderne'::text,'plus moderne'::text,'la plus moderne'::text,'C''est la fin ! La tour est plus moderne que son immeuble !'::text),
(305576,33953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu son! Kule onun blokundan ...!'::text,'daha modern'::text,'daha modern'::text,'en modern'::text,'Bu son! Kule onun blokundan daha modern!'::text),
(305577,33953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a vég! A torony ..., mint a háza!'::text,'modernebb'::text,'modernebb'::text,'legmodernebb'::text,'Ez a vég! A torony modernebb, mint a háza!'::text),
(305589,33955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also, angeblich hasst er moderne Gebäude, ... er hat zu einem hinaufgestarrt.'::text,'aber'::text,'also'::text,'weil'::text,'Also, angeblich hasst er moderne Gebäude, aber er hat zu einem hinaufgestarrt.'::text),
(305593,33955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, він ненавидить сучасні будівлі, ... витріщався на одну.'::text,'але'::text,'тому'::text,'бо'::text,'Коротше, кажуть, він ненавидить сучасні будівлі, але витріщався на одну.'::text),
(305592,33955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ver, dicen que odia los edificios modernos, ... se quedó mirando uno hacia arriba.'::text,'pero'::text,'así que'::text,'porque'::text,'A ver, dicen que odia los edificios modernos, pero se quedó mirando uno hacia arriba.'::text),
(305591,33955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment il déteste les bâtiments modernes, ... il en a fixé un du regard.'::text,'mais'::text,'donc'::text,'parce que'::text,'Bon, apparemment il déteste les bâtiments modernes, mais il en a fixé un du regard.'::text),
(305594,33955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, güya modern binalardan nefret ediyormuş ... birine dik dik bakıp durmuş.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Neyse, güya modern binalardan nefret ediyormuş ama birine dik dik bakıp durmuş.'::text),
(305595,33955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval állítólag utálja a modern épületeket, ... felbámult az egyikre.'::text,'de'::text,'ezért'::text,'mert'::text,'Szóval állítólag utálja a modern épületeket, de felbámult az egyikre.'::text),
(311817,34647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihr Buch an der Bushaltestelle.'::text,'liest'::text,'lesen'::text,'lesend'::text,'Sie liest ihr Buch an der Bushaltestelle.'::text),
(311821,34647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свою книжку на зупинці.'::text,'читає'::text,'читати'::text,'читаючи'::text,'Вона читає свою книжку на зупинці.'::text),
(311820,34647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su libro en la parada del autobús.'::text,'lee'::text,'leer'::text,'leyendo'::text,'Ella lee su libro en la parada del autobús.'::text),
(311819,34647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... son livre à l''arrêt de bus.'::text,'lit'::text,'lire'::text,'lisant'::text,'Elle lit son livre à l''arrêt de bus.'::text),
(311822,34647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otobüs durağında kitabını ...'::text,'okur'::text,'okumak'::text,'okuyarak'::text,'Otobüs durağında kitabını okur.'::text),
(311823,34647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a buszmegállóban ... a könyvét.'::text,'olvassa'::text,'olvasni'::text,'olvasó'::text,'Ő a buszmegállóban olvassa a könyvét.'::text),
(311835,34649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bus-Deadline in 10 Minuten: Bis dahin ... sie das letzte Kapitel lesen.'::text,'wird'::text,'liest'::text,'lesen'::text,'Bus-Deadline in 10 Minuten: Bis dahin wird sie das letzte Kapitel lesen.'::text),
(311839,34649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн автобуса через 10 хвилин: вона до того часу ... останній розділ.'::text,'дочитає'::text,'читає'::text,'читати'::text,'Дедлайн автобуса через 10 хвилин: вона до того часу дочитає останній розділ.'::text),
(311838,34649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline del bus en 10 minutos: para entonces ... el último capítulo.'::text,'leerá'::text,'lee'::text,'leer'::text,'Deadline del bus en 10 minutos: para entonces leerá el último capítulo.'::text),
(311837,34649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline du bus dans 10 minutes : d''ici là, elle ... le dernier chapitre.'::text,'lira'::text,'lit'::text,'lire'::text,'Deadline du bus dans 10 minutes : d''ici là, elle lira le dernier chapitre.'::text),
(311840,34649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Otobüs için son tarih 10 dakika sonra: o zamana kadar son bölümü ...'::text,'okuyacak'::text,'okur'::text,'okumak'::text,'Otobüs için son tarih 10 dakika sonra: o zamana kadar son bölümü okuyacak.'::text),
(311841,34649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Busz-határidő 10 perc múlva: addigra ... az utolsó fejezetet.'::text,'el fogja olvasni'::text,'olvassa'::text,'olvasni'::text,'Busz-határidő 10 perc múlva: addigra el fogja olvasni az utolsó fejezetet.'::text),
(311844,34650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ein Buch, also ... sie es an der Bushaltestelle lesen.'::text,'wird'::text,'wird'::text,'wird'::text,'Sie hat ein Buch, also wird sie es an der Bushaltestelle lesen.'::text),
(311848,34650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї є книжка, тож вона ... її на зупинці.'::text,'збирається читати'::text,'збирається читати'::text,'збирається читати'::text,'У неї є книжка, тож вона збирається читати її на зупинці.'::text),
(311847,34650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un libro, así que lo ... en la parada del autobús.'::text,'va a leer'::text,'va a leer'::text,'va a leer'::text,'Tiene un libro, así que lo va a leer en la parada del autobús.'::text),
(311846,34650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a un livre, donc elle ... le lire à l''arrêt de bus.'::text,'va'::text,'va'::text,'va'::text,'Elle a un livre, donc elle va le lire à l''arrêt de bus.'::text),
(311849,34650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kitabı var, bu yüzden onu otobüs durağında ...'::text,'okuyacak'::text,'okuyacak'::text,'okuyacak'::text,'Bir kitabı var, bu yüzden onu otobüs durağında okuyacak.'::text),
(311850,34650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy könyve, ezért a buszmegállóban ...'::text,'olvasni fogja'::text,'olvasni fogja'::text,'olvasni fogja'::text,'Van egy könyve, ezért a buszmegállóban olvasni fogja.'::text),
(311862,34652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie wieder! Ich ... aufhören zu lesen und auf den Bus achten!'::text,'muss'::text,'muss'::text,'sollte'::text,'Nie wieder! Ich muss aufhören zu lesen und auf den Bus achten!'::text),
(311866,34652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи більше! Я ... перестати читати й стежити за автобусом!'::text,'мушу'::text,'маю'::text,'мала б'::text,'Ніколи більше! Я мушу перестати читати й стежити за автобусом!'::text),
(311865,34652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca más! ¡... dejar de leer y estar atenta al autobús!'::text,'Debo'::text,'Tengo que'::text,'Debería'::text,'¡Nunca más! ¡Debo dejar de leer y estar atenta al autobús!'::text),
(311864,34652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus jamais ! Je ... arrêter de lire et guetter le bus !'::text,'dois'::text,'dois'::text,'devrais'::text,'Plus jamais ! Je dois arrêter de lire et guetter le bus !'::text),
(311867,34652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla! Okumayı bırakıp otobüsü ...!'::text,'gözlemeliyim'::text,'gözlemek zorundayım'::text,'gözlemeliyim'::text,'Bir daha asla! Okumayı bırakıp otobüsü gözlemeliyim!'::text),
(311868,34652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha többé! ... abbahagynom az olvasást, és figyelnem a buszt!'::text,'Kell'::text,'Kell'::text,'Kellene'::text,'Soha többé! Kell abbahagynom az olvasást, és figyelnem a buszt!'::text),
(311871,34653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absoluter Albtraum! Sie ... aufhören zu lesen und nach dem Bus schauen!'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Absoluter Albtraum! Sie sollte aufhören zu lesen und nach dem Bus schauen!'::text),
(311875,34653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній жах! Вона ... перестати читати й виглядати автобус!'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Справжній жах! Вона мала б перестати читати й виглядати автобус!'::text),
(311874,34653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla total! ¡... dejar de leer y buscar el autobús!'::text,'Debería'::text,'Debería'::text,'Debería'::text,'¡Pesadilla total! ¡Debería dejar de leer y buscar el autobús!'::text),
(311873,34653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar absolu ! Elle ... arrêter de lire et chercher le bus des yeux !'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Cauchemar absolu ! Elle devrait arrêter de lire et chercher le bus des yeux !'::text),
(311876,34653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir kâbus! Okumayı bırakıp otobüsü ...!'::text,'kollamalı'::text,'kollamalı'::text,'kollamalı'::text,'Tam bir kâbus! Okumayı bırakıp otobüsü kollamalı!'::text),
(311877,34653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totális rémálom! ... abbahagynia az olvasást, és a buszt keresnie!'::text,'Kellene'::text,'Kellene'::text,'Kellene'::text,'Totális rémálom! Kellene abbahagynia az olvasást, és a buszt keresnie!'::text),
(311880,34654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich hat sie den ganzen Morgen gelesen, ... hat sie den ersten Bus verpasst.'::text,'also'::text,'aber'::text,'weil'::text,'Bestie, angeblich hat sie den ganzen Morgen gelesen, also hat sie den ersten Bus verpasst.'::text),
(311884,34654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, кажуть, вона весь ранок читала, ... пропустила перший автобус.'::text,'тому'::text,'але'::text,'бо'::text,'Подружко, кажуть, вона весь ранок читала, тому пропустила перший автобус.'::text),
(311883,34654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dicen que se pasó toda la mañana leyendo, ... perdió el primer autobús.'::text,'así que'::text,'pero'::text,'porque'::text,'Amiga, dicen que se pasó toda la mañana leyendo, así que perdió el primer autobús.'::text),
(311882,34654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma chérie, apparemment elle a lu toute la matinée, ... elle a raté le premier bus.'::text,'donc'::text,'mais'::text,'parce que'::text,'Ma chérie, apparemment elle a lu toute la matinée, donc elle a raté le premier bus.'::text),
(311885,34654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, güya bütün sabah kitap okumuş ... ilk otobüsü kaçırmış.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Kankam, güya bütün sabah kitap okumuş bu yüzden ilk otobüsü kaçırmış.'::text),
(311886,34654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barátnőm, állítólag egész délelőtt olvasott, ... lekéste az első buszt.'::text,'ezért'::text,'de'::text,'mert'::text,'Barátnőm, állítólag egész délelőtt olvasott, ezért lekéste az első buszt.'::text),
(325398,36156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du ... in Sekunden nach oben und jubeltest ganz oben.'::text,'ranntest'::text,'rennst'::text,NULL::text,'Respekt: Du ranntest in Sekunden nach oben und jubeltest ganz oben.'::text),
(325402,36156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти ... нагору за лічені секунди й радів на самому верху.'::text,'вибіг'::text,'вибігаєш'::text,NULL::text,'Респект: ти вибіг нагору за лічені секунди й радів на самому верху.'::text),
(325401,36156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: ... arriba en segundos y lo celebraste en lo alto.'::text,'subiste corriendo'::text,'subes corriendo'::text,NULL::text,'Respeto: subiste corriendo arriba en segundos y lo celebraste en lo alto.'::text),
(325400,36156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu ... en haut en quelques secondes et tu as crié de joie au sommet.'::text,'as couru'::text,'cours'::text,NULL::text,'Respect : tu as couru en haut en quelques secondes et tu as crié de joie au sommet.'::text),
(325403,36156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar: saniyeler içinde yukarı ... ve tepede sevinçle bağırdın.'::text,'koştun'::text,'koşarsın'::text,NULL::text,'Saygılar: saniyeler içinde yukarı koştun ve tepede sevinçle bağırdın.'::text),
(325404,36156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le a kalappal: pár másodperc alatt ... az emeletre, és fent ujjongtál.'::text,'felrohantál'::text,'felrohansz'::text,NULL::text,'Le a kalappal: pár másodperc alatt felrohantál az emeletre, és fent ujjongtál.'::text),
(325407,36157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch, du ... nach oben wie ein echter Stadtentdecker.'::text,'kletterst'::text,'klettert'::text,'kletterst'::text,'Irgendwie ikonisch, du kletterst nach oben wie ein echter Stadtentdecker.'::text),
(325411,36157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи іконічно: ти ... нагору, як справжній дослідник міста.'::text,'піднімаєшся'::text,'піднімається'::text,'піднімаєшся'::text,'Трохи іконічно: ти піднімаєшся нагору, як справжній дослідник міста.'::text),
(325410,36157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco icónico: ... arriba como un auténtico explorador urbano.'::text,'estás subiendo'::text,'sube'::text,'estás subiendo'::text,'Un poco icónico: estás subiendo arriba como un auténtico explorador urbano.'::text),
(325409,36157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique : tu ... à l''étage comme un vrai explorateur urbain.'::text,'es en train de monter'::text,'monte'::text,'es en train de monter'::text,'Un peu iconique : tu es en train de monter à l''étage comme un vrai explorateur urbain.'::text),
(325412,36157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz ikonik, gerçek bir şehir kaşifi gibi yukarı ...'::text,'tırmanıyorsun'::text,'tırmanır'::text,'tırmanıyorsun'::text,'Biraz ikonik, gerçek bir şehir kaşifi gibi yukarı tırmanıyorsun.'::text),
(325413,36157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit ikonikus, úgy ... fel az emeletre, mint egy igazi városfelfedező.'::text,'mászol'::text,'mászik'::text,'mászol'::text,'Kicsit ikonikus, úgy mászol fel az emeletre, mint egy igazi városfelfedező.'::text),
(325416,36158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du fährst jeden Tag Bus, aber gerade ... du oben. Stark.'::text,'sitzt'::text,'sitzt'::text,NULL::text,'Du fährst jeden Tag Bus, aber gerade sitzt du oben. Stark.'::text),
(325420,36158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти щодня їздиш автобусом, але саме зараз ... нагорі. Стильно.'::text,'сидиш'::text,'сидиш'::text,NULL::text,'Ти щодня їздиш автобусом, але саме зараз сидиш нагорі. Стильно.'::text),
(325419,36158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Coges el autobús todos los días, pero ahora mismo ... arriba. Qué estilo.'::text,'estás sentado'::text,'te sientas'::text,NULL::text,'Coges el autobús todos los días, pero ahora mismo estás sentado arriba. Qué estilo.'::text),
(325418,36158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu prends le bus tous les jours, mais là tu ... en haut. Stylé.'::text,'es assis'::text,'t''assois'::text,NULL::text,'Tu prends le bus tous les jours, mais là tu es assis en haut. Stylé.'::text),
(325421,36158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün otobüse biniyorsun ama şu an ... üst katta. Çok şık.'::text,'oturuyorsun'::text,'oturursun'::text,NULL::text,'Her gün otobüse biniyorsun ama şu an oturuyorsun üst katta. Çok şık.'::text),
(325422,36158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nap busszal jársz, de most épp ... fent. Stílusos.'::text,'ülsz'::text,'ülsz'::text,NULL::text,'Minden nap busszal jársz, de most épp ülsz fent. Stílusos.'::text),
(325425,36159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein sehr ruhiger Fahrgast, klar. Oben ... er morgen wieder schreien.'::text,'wird'::text,'ist'::text,'war'::text,'Ein sehr ruhiger Fahrgast, klar. Oben wird er morgen wieder schreien.'::text),
(325429,36159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже спокійний пасажир, очевидно. Нагорі він завтра знову ... кричати.'::text,'буде'::text,'є'::text,'був'::text,'Дуже спокійний пасажир, очевидно. Нагорі він завтра знову буде кричати.'::text),
(325428,36159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pasajero muy tranquilo, obviamente. Arriba, mañana ... gritar otra vez.'::text,''::text,'está'::text,'estaba'::text,'Un pasajero muy tranquilo, obviamente. Arriba, mañana gritar otra vez.'::text),
(325427,36159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un passager très calme, évidemment. En haut, il ... crier encore demain.'::text,''::text,'est'::text,'était'::text,'Un passager très calme, évidemment. En haut, il crier encore demain.'::text),
(325430,36159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sakin bir yolcu, belli ki. Üst katta yarın yine ...'::text,'bağıracak'::text,NULL::text,'idi'::text,'Çok sakin bir yolcu, belli ki. Üst katta yarın yine bağıracak.'::text),
(325431,36159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon nyugodt utas, nyilván. Fent holnap megint ... kiabálni.'::text,'fog'::text,'van'::text,'volt'::text,'Nagyon nyugodt utas, nyilván. Fent holnap megint fog kiabálni.'::text),
(325434,36160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, ein total langweiliger Bus. Die Aussicht oben ist ... als unten.'::text,'besser'::text,'besser'::text,'am besten'::text,'Klar, ein total langweiliger Bus. Die Aussicht oben ist besser als unten.'::text),
(325438,36160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, нудний автобус. Вид нагорі ..., ніж унизу.'::text,'кращий'::text,'кращий'::text,'найкращий'::text,'Очевидно, нудний автобус. Вид нагорі кращий, ніж унизу.'::text),
(325437,36160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente, un autobús aburrido. La vista de arriba es ... que la de abajo.'::text,'mejor'::text,'mejor'::text,'la mejor'::text,'Claramente, un autobús aburrido. La vista de arriba es mejor que la de abajo.'::text),
(325436,36160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un bus ennuyeux. La vue en haut est ... qu''en bas.'::text,'meilleure'::text,'meilleure'::text,'la meilleure'::text,'Clairement un bus ennuyeux. La vue en haut est meilleure qu''en bas.'::text),
(325439,36160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sıkıcı bir otobüs. Üst kattaki manzara alt kattakinden ...'::text,'daha iyi'::text,'daha iyi'::text,'en iyi'::text,'Belli ki sıkıcı bir otobüs. Üst kattaki manzara alt kattakinden daha iyi.'::text),
(325440,36160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egy unalmas busz. Fentről ... a kilátás, mint lentről.'::text,'jobb'::text,'jobb'::text,'legjobb'::text,'Nyilván egy unalmas busz. Fentről jobb a kilátás, mint lentről.'::text),
(325443,36161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er rennt ... nach oben aufs Oberdeck.'::text,'fröhlich'::text,'fröhlich'::text,'fröhlich'::text,'Er rennt fröhlich nach oben aufs Oberdeck.'::text),
(325447,36161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... біжить нагору на верхній поверх.'::text,'радісно'::text,'радісний'::text,'радісно'::text,'Він радісно біжить нагору на верхній поверх.'::text),
(325446,36161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sube corriendo ... hasta el piso de arriba.'::text,'alegremente'::text,'alegre'::text,'alegremente'::text,'Sube corriendo alegremente hasta el piso de arriba.'::text),
(325445,36161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il court ... à l''étage supérieur.'::text,'joyeusement'::text,'joyeux'::text,'joyeusement'::text,'Il court joyeusement à l''étage supérieur.'::text),
(325448,36161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üst kata ... koşuyor.'::text,'mutlulukla'::text,'mutlu'::text,'mutlulukla'::text,'Üst kata mutlulukla koşuyor.'::text),
(325449,36161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... fut fel a felső szintre.'::text,'Boldogan'::text,'Boldog'::text,'Boldogan'::text,'Boldogan fut fel a felső szintre.'::text),
(298614,33180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Metzger verkauft normalerweise Schinken, aber gestern ... er nur Steak.'::text,'verkaufte'::text,'verkauft'::text,NULL::text,'Der Metzger verkauft normalerweise Schinken, aber gestern verkaufte er nur Steak.'::text),
(298618,33180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'М''ясник зазвичай продає шинку, але вчора він ... тільки стейк.'::text,'продавав'::text,'продає'::text,NULL::text,'М''ясник зазвичай продає шинку, але вчора він продавав тільки стейк.'::text),
(298617,33180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El carnicero suele vender jamón, pero ayer ... solo filete.'::text,'vendió'::text,'vende'::text,NULL::text,'El carnicero suele vender jamón, pero ayer vendió solo filete.'::text),
