(298843,33205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї є план: завтра вона знову ... на повну.'::text,'збирається тренуватися'::text,'збирається тренуватися'::text,'збирається тренуватися'::text,'У неї є план: завтра вона знову збирається тренуватися на повну.'::text),
(298842,33205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un plan: mañana ... duro otra vez.'::text,'va a entrenar'::text,'va a entrenar'::text,'va a entrenar'::text,'Tiene un plan: mañana va a entrenar duro otra vez.'::text),
(298841,33205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a un plan : elle ... dur encore demain.'::text,'va s''entraîner'::text,'va s''entraîner'::text,'va s''entraîner'::text,'Elle a un plan : elle va s''entraîner dur encore demain.'::text),
(298844,33205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir planı var: yarın yine sıkı antrenman ...'::text,'yapacak'::text,'yapacak'::text,'yapacak'::text,'Bir planı var: yarın yine sıkı antrenman yapacak.'::text),
(298845,33205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy terve: holnap megint keményen ...'::text,'fog edzeni'::text,'fog edzeni'::text,'fog edzeni'::text,'Van egy terve: holnap megint keményen fog edzeni.'::text),
(298848,33206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Beine zittern. Die letzte Minute ... sehr hart sein.'::text,'wird'::text,'wird'::text,NULL::text,'Ihre Beine zittern. Die letzte Minute wird sehr hart sein.'::text),
(298852,33206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її ноги тремтять. Остання хвилина ... дуже важкою.'::text,'збирається бути'::text,'буде'::text,NULL::text,'Її ноги тремтять. Остання хвилина збирається бути дуже важкою.'::text),
(298851,33206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tiemblan las piernas. El último minuto ... muy duro.'::text,'va a ser'::text,'será'::text,NULL::text,'Le tiemblan las piernas. El último minuto va a ser muy duro.'::text),
(298850,33206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses jambes tremblent. La dernière minute ... très dure.'::text,'va être'::text,'sera'::text,NULL::text,'Ses jambes tremblent. La dernière minute va être très dure.'::text),
(298853,33206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bacakları titriyor. Son dakika çok zor ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Bacakları titriyor. Son dakika çok zor olacak.'::text),
(298854,33206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remeg a lába. Az utolsó perc nagyon kemény ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Remeg a lába. Az utolsó perc nagyon kemény lesz.'::text),
(298866,33208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Der Trainer sagt, sie ... eine Stunde lang hart in die Pedale treten!'::text,'muss'::text,'muss'::text,'muss nicht'::text,'Albtraum! Der Trainer sagt, sie muss eine Stunde lang hart in die Pedale treten!'::text),
(298870,33208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Тренер каже, що вона ... годину крутити педалі на повну!'::text,'має'::text,'мусить'::text,'не має'::text,'Жах! Тренер каже, що вона має годину крутити педалі на повну!'::text),
(298869,33208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El entrenador dice que ... pedalear fuerte durante una hora!'::text,'tiene que'::text,'debe'::text,'no tiene que'::text,'¡Pesadilla! ¡El entrenador dice que tiene que pedalear fuerte durante una hora!'::text),
(298868,33208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le coach dit qu''elle ... pédaler fort pendant une heure !'::text,'doit'::text,'doit'::text,'ne doit pas'::text,'Cauchemar ! Le coach dit qu''elle doit pédaler fort pendant une heure !'::text),
(298871,33208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Antrenör diyor ki bir saat boyunca sert pedal ...!'::text,'çevirmek zorunda'::text,'çevirmeli'::text,'çevirmek zorunda değil'::text,'Kâbus! Antrenör diyor ki bir saat boyunca sert pedal çevirmek zorunda!'::text),
(298872,33208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Az edző azt mondja, egy órán át keményen ... tekernie!'::text,'kell'::text,'kell'::text,'nem kell'::text,'Rémálom! Az edző azt mondja, egy órán át keményen kell tekernie!'::text),
(298875,33209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist so hart! Du ... eine Pause machen, sonst klappst du zusammen!'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Das ist so hart! Du solltest eine Pause machen, sonst klappst du zusammen!'::text),
(298879,33209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це так важко! Ти ... зробити перерву, бо інакше впадеш!'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Це так важко! Ти мала б зробити перерву, бо інакше впадеш!'::text),
(298878,33209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es durísimo! ¡... tomarte un descanso o te vas a desmayar!'::text,'Deberías'::text,'Deberías'::text,'Deberías'::text,'¡Es durísimo! ¡Deberías tomarte un descanso o te vas a desmayar!'::text),
(298877,33209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est trop dur ! Tu ... faire une pause, sinon tu vas t''effondrer !'::text,'devrais'::text,'devrais'::text,'devrais'::text,'C''est trop dur ! Tu devrais faire une pause, sinon tu vas t''effondrer !'::text),
(298880,33209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok zor! Mola ..., yoksa yığılıp kalacaksın!'::text,'vermelisin'::text,'vermelisin'::text,'vermelisin'::text,'Çok zor! Mola vermelisin, yoksa yığılıp kalacaksın!'::text),
(298881,33209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez annyira kemény! ... tartanod egy szünetet, különben összeesel!'::text,'Kellene'::text,'Kellene'::text,'Kellene'::text,'Ez annyira kemény! Kellene tartanod egy szünetet, különben összeesel!'::text),
(298884,33210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie tritt so ... in die Pedale, dass ihr Gesicht knallrot ist!'::text,'kräftig'::text,'kaum'::text,'robust'::text,'Sie tritt so kräftig in die Pedale, dass ihr Gesicht knallrot ist!'::text),
(298888,33210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона крутить педалі так ..., що її обличчя зовсім червоне!'::text,'сильно'::text,'ледве'::text,'витривалий'::text,'Вона крутить педалі так сильно, що її обличчя зовсім червоне!'::text),
(298887,33210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pedalea tan ... que tiene la cara completamente roja!'::text,'fuerte'::text,'apenas'::text,'resistente'::text,'¡Pedalea tan fuerte que tiene la cara completamente roja!'::text),
(298886,33210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pédale si ... que son visage est tout rouge !'::text,'fort'::text,'à peine'::text,'robuste'::text,'Elle pédale si fort que son visage est tout rouge !'::text),
(298889,33210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar ... pedal çeviriyor ki yüzü kıpkırmızı!'::text,'sert'::text,'zar zor'::text,'dayanıklı'::text,'O kadar sert pedal çeviriyor ki yüzü kıpkırmızı!'::text),
(298890,33210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan ... teker, hogy teljesen vörös az arca!'::text,'keményen'::text,'alig'::text,'edzett'::text,'Olyan keményen teker, hogy teljesen vörös az arca!'::text),
(298893,33211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie meinte, der Kurs war hart, ... sie hat nicht aufgehört.'::text,'aber'::text,'also'::text,'weil'::text,'Bestie, sie meinte, der Kurs war hart, aber sie hat nicht aufgehört.'::text),
(298897,33211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, вона казала, що заняття було важке, ... вона не зупинилася.'::text,'але'::text,'тому'::text,'бо'::text,'Подружко, вона казала, що заняття було важке, але вона не зупинилася.'::text),
(298896,33211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dijo que la clase fue dura, ... no paró.'::text,'pero'::text,'así que'::text,'porque'::text,'Amiga, dijo que la clase fue dura, pero no paró.'::text),
(298895,33211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma chérie, elle a dit que le cours était dur, ... elle ne s''est pas arrêtée.'::text,'mais'::text,'donc'::text,'parce que'::text,'Ma chérie, elle a dit que le cours était dur, mais elle ne s''est pas arrêtée.'::text),
(298898,33211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, dersin zor olduğunu söyledi ... hiç durmadı.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kankam, dersin zor olduğunu söyledi ama hiç durmadı.'::text),
(298899,33211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barátnőm, azt mondta, kemény volt az óra, ... nem állt meg.'::text,'de'::text,'ezért'::text,'mert'::text,'Barátnőm, azt mondta, kemény volt az óra, de nem állt meg.'::text),
(294987,32777,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das große Objektiv auf die Stadt.'::text,'fokussiert'::text,'fokussieren'::text,'fokussierend'::text,'Sie fokussiert das große Objektiv auf die Stadt.'::text),
(294991,32777,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... великий об''єктив на місто.'::text,'наводить'::text,'наводити'::text,'наводячи'::text,'Вона наводить великий об''єктив на місто.'::text),
(294990,32777,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el objetivo grande en la ciudad.'::text,'enfoca'::text,'enfocar'::text,'enfocando'::text,'Ella enfoca el objetivo grande en la ciudad.'::text),
(294989,32777,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le gros objectif sur la ville.'::text,'braque'::text,'braquer'::text,'braquant'::text,'Elle braque le gros objectif sur la ville.'::text),
(294992,32777,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük objektifi şehre ...'::text,'odaklar'::text,'odaklamak'::text,'odaklayarak'::text,'Büyük objektifi şehre odaklar.'::text),
(294993,32777,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a nagy objektívet ... a városra.'::text,'fókuszálja'::text,'fókuszálni'::text,'fókuszáló'::text,'Ő a nagy objektívet fókuszálja a városra.'::text),
(295005,32779,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber ... stellst du das Objektiv so schnell scharf? Beeindruckend.'::text,'wie'::text,'wer'::text,'wo'::text,'Okay, aber wie stellst du das Objektiv so schnell scharf? Beeindruckend.'::text),
(295009,32779,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але ... ти так швидко наводиш різкість на тому об''єктиві? Вражає.'::text,'як'::text,'хто'::text,'де'::text,'Окей, але як ти так швидко наводиш різкість на тому об''єктиві? Вражає.'::text),
(295008,32779,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero ¿... enfocas ese objetivo tan rápido? Impresionante.'::text,'cómo'::text,'quién'::text,'dónde'::text,'Vale, pero ¿cómo enfocas ese objetivo tan rápido? Impresionante.'::text),
(295007,32779,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''accord, mais ... tu fais la mise au point si vite ? Impressionnant.'::text,'comment'::text,'qui'::text,'où'::text,'D''accord, mais comment tu fais la mise au point si vite ? Impressionnant.'::text),
(295010,32779,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam da o objektifi ... bu kadar hızlı odaklıyorsun? Etkileyici.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Tamam da o objektifi nasıl bu kadar hızlı odaklıyorsun? Etkileyici.'::text),
(295011,32779,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de ... állítod élesre olyan gyorsan azt az objektívet? Lenyűgöző.'::text,'hogyan'::text,'ki'::text,'hol'::text,'Oké, de hogyan állítod élesre olyan gyorsan azt az objektívet? Lenyűgöző.'::text),
(295014,32780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Sie ... die Kamera mit einem Zwinkern scharf.'::text,'stellte'::text,'stellen'::text,'stellend'::text,'Ein echter Profi: Sie stellte die Kamera mit einem Zwinkern scharf.'::text),
(295018,32780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжня професіоналка: вона ... камеру з підморгуванням.'::text,'сфокусувала'::text,'фокусувати'::text,'фокусуючи'::text,'Справжня професіоналка: вона сфокусувала камеру з підморгуванням.'::text),
(295017,32780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una auténtica profesional: ... la cámara con un guiño.'::text,'enfocó'::text,'enfocar'::text,'enfocando'::text,'Una auténtica profesional: enfocó la cámara con un guiño.'::text),
(295016,32780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une vraie pro : elle ... l''appareil avec un clin d''œil.'::text,'a réglé'::text,'régler'::text,'réglant'::text,'Une vraie pro : elle a réglé l''appareil avec un clin d''œil.'::text),
(295019,32780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir profesyonel: fotoğraf makinesini göz kırparak ...'::text,'odakladı'::text,'odaklamak'::text,'odaklayarak'::text,'Tam bir profesyonel: fotoğraf makinesini göz kırparak odakladı.'::text),
(295020,32780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: egy kacsintással ... a fényképezőgépet.'::text,'élesre állította'::text,'élesre állítani'::text,'élesre állító'::text,'Igazi profi: egy kacsintással élesre állította a fényképezőgépet.'::text),
(295032,32782,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar ein Profi: Normalerweise stellt sie in Sekunden scharf, aber heute ... sie ewig.'::text,'fokussiert'::text,'fokussiert'::text,NULL::text,'Klar ein Profi: Normalerweise stellt sie in Sekunden scharf, aber heute fokussiert sie ewig.'::text),
(295036,32782,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, профі: зазвичай вона наводить різкість за секунди, але сьогодні ... цілу вічність.'::text,'наводить'::text,'наводить'::text,NULL::text,'Очевидно, профі: зазвичай вона наводить різкість за секунди, але сьогодні наводить цілу вічність.'::text),
(295035,32782,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda una profesional: normalmente enfoca en segundos, pero hoy ... una eternidad.'::text,'está enfocando'::text,'enfoca'::text,NULL::text,'Toda una profesional: normalmente enfoca en segundos, pero hoy está enfocando una eternidad.'::text),
(295034,32782,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement une pro : d''habitude, elle règle la netteté en quelques secondes, mais aujourd''hui elle ... pendant une éternité.'::text,'est en train de régler'::text,'règle'::text,NULL::text,'Clairement une pro : d''habitude, elle règle la netteté en quelques secondes, mais aujourd''hui elle est en train de régler pendant une éternité.'::text),
(295037,32782,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki profesyonel: genelde saniyeler içinde odaklar ama bugün saatlerdir ...'::text,'odaklıyor'::text,'odaklar'::text,NULL::text,'Belli ki profesyonel: genelde saniyeler içinde odaklar ama bugün saatlerdir odaklıyor.'::text),
(295038,32782,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván profi: általában másodpercek alatt élesít, de ma egy örökkévalóságig ...'::text,'élesít'::text,'élesít'::text,NULL::text,'Nyilván profi: általában másodpercek alatt élesít, de ma egy örökkévalóságig élesít.'::text),
(295041,32783,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist eine Katastrophe! Warte, ich ... dir das Objektiv fokussieren!'::text,'werde'::text,'fokussiere'::text,'fokussierte'::text,'Das ist eine Katastrophe! Warte, ich werde dir das Objektiv fokussieren!'::text),
(295045,32783,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це катастрофа! Зачекай, я ... тобі об''єктив!'::text,'налаштую'::text,'налаштовую'::text,'налаштував'::text,'Це катастрофа! Зачекай, я налаштую тобі об''єктив!'::text),
(295044,32783,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es un desastre! ¡Espera, te ... el objetivo!'::text,'enfocaré'::text,'enfoco'::text,'enfoqué'::text,'¡Es un desastre! ¡Espera, te enfocaré el objetivo!'::text),
(295043,32783,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est une catastrophe ! Attends, je ... l''objectif pour toi !'::text,'réglerai'::text,'règle'::text,'ai réglé'::text,'C''est une catastrophe ! Attends, je réglerai l''objectif pour toi !'::text),
(295046,32783,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Dur, objektifi senin için ben ...!'::text,'odaklayacağım'::text,'odaklarım'::text,'odakladım'::text,'Felaket! Dur, objektifi senin için ben odaklayacağım!'::text),
(295047,32783,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez katasztrófa! Várj, ... neked az objektívet!'::text,'be fogom állítani'::text,'beállítom'::text,'beállítottam'::text,'Ez katasztrófa! Várj, be fogom állítani neked az objektívet!'::text),
(295050,32784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat einen Plan: Sie ... bei Sonnenuntergang auf die Dächer fokussieren.'::text,'wird'::text,'wird'::text,'wird'::text,'Sie hat einen Plan: Sie wird bei Sonnenuntergang auf die Dächer fokussieren.'::text),
(295054,32784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї є план: на заході сонця вона ... на дахах.'::text,'збирається фокусуватися'::text,'збирається фокусуватися'::text,'збирається фокусуватися'::text,'У неї є план: на заході сонця вона збирається фокусуватися на дахах.'::text),
(295053,32784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un plan: al atardecer ... en los tejados.'::text,'va a enfocar'::text,'va a enfocar'::text,'va a enfocar'::text,'Tiene un plan: al atardecer va a enfocar en los tejados.'::text),
(295052,32784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a un plan : au coucher du soleil, elle ... sur les toits.'::text,'va faire la mise au point'::text,'va faire la mise au point'::text,'va faire la mise au point'::text,'Elle a un plan : au coucher du soleil, elle va faire la mise au point sur les toits.'::text),
(295055,32784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir planı var: gün batımında çatılara ...'::text,'odaklanacak'::text,'odaklanacak'::text,'odaklanacak'::text,'Bir planı var: gün batımında çatılara odaklanacak.'::text),
