(310787,34532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, genelde pizza sipariş eder ama bu akşam yemek ..., yemin ederim.'::text,'hazırlıyor'::text,'hazırlar'::text,NULL::text,'Kanka, genelde pizza sipariş eder ama bu akşam yemek hazırlıyor, yemin ederim.'::text),
(310788,34532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, általában pizzát rendel, de ma este ... a vacsorát, komolyan.'::text,'készíti'::text,'készíti'::text,NULL::text,'Tesó, általában pizzát rendel, de ma este készíti a vacsorát, komolyan.'::text),
(310791,34533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline: 20 Uhr. Sie ... den Raum rechtzeitig vorbereiten.'::text,'wird'::text,'bereitet'::text,'bereitete'::text,'Deadline: 20 Uhr. Sie wird den Raum rechtzeitig vorbereiten.'::text),
(310795,34533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн: 20:00. Вона ... кімнату вчасно.'::text,'підготує'::text,'готує'::text,'підготувала'::text,'Дедлайн: 20:00. Вона підготує кімнату вчасно.'::text),
(310794,34533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fecha límite: 20:00. ... la sala a tiempo.'::text,'Preparará'::text,'Prepara'::text,'Preparó'::text,'Fecha límite: 20:00. Preparará la sala a tiempo.'::text),
(310793,34533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline : 20 h. Elle ... la salle à temps.'::text,'préparera'::text,'prépare'::text,'a préparé'::text,'Deadline : 20 h. Elle préparera la salle à temps.'::text),
(310796,34533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son tarih: 20.00. Odayı zamanında ...'::text,'hazırlayacak'::text,'hazırlar'::text,'hazırladı'::text,'Son tarih: 20.00. Odayı zamanında hazırlayacak.'::text),
(310797,34533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Határidő: este 8. Időben ... a termet.'::text,'elő fogja készíteni'::text,'előkészíti'::text,'előkészítette'::text,'Határidő: este 8. Időben elő fogja készíteni a termet.'::text),
(310809,34535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, ich glaube, du ... das beste Abendessen der Stadt zubereiten.'::text,'wirst'::text,'wirst'::text,NULL::text,'Ganz ehrlich, ich glaube, du wirst das beste Abendessen der Stadt zubereiten.'::text),
(310813,34535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, думаю, ти ... найкращу вечерю в місті.'::text,'приготуєш'::text,'збираєшся приготувати'::text,NULL::text,'Чесно, думаю, ти приготуєш найкращу вечерю в місті.'::text),
(310812,34535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, creo que ... la mejor cena de la ciudad.'::text,'prepararás'::text,'vas a preparar'::text,NULL::text,'La verdad, creo que prepararás la mejor cena de la ciudad.'::text),
(310811,34535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, je pense que tu ... le meilleur dîner de la ville.'::text,'prépareras'::text,'vas préparer'::text,NULL::text,'Franchement, je pense que tu prépareras le meilleur dîner de la ville.'::text),
(310814,34535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bence şehrin en iyi yemeğini sen ...'::text,'hazırlayacaksın'::text,'hazırlayacaksın'::text,NULL::text,'Açıkçası bence şehrin en iyi yemeğini sen hazırlayacaksın.'::text),
(310815,34535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, szerintem te ... a város legjobb vacsoráját.'::text,'fogod elkészíteni'::text,'fogod elkészíteni'::text,NULL::text,'Őszintén, szerintem te fogod elkészíteni a város legjobb vacsoráját.'::text),
(310818,34536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ist ja deine eigene Idee, ehrlich: Du ... jede Kerze selbst vorbereiten.'::text,'musst'::text,'musst'::text,'solltest'::text,'Ist ja deine eigene Idee, ehrlich: Du musst jede Kerze selbst vorbereiten.'::text),
(310822,34536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ж твоя власна ідея, чесно: ти ... підготувати кожну свічку сама.'::text,'мусиш'::text,'маєш'::text,'мала б'::text,'Це ж твоя власна ідея, чесно: ти мусиш підготувати кожну свічку сама.'::text),
(310821,34536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es tu propia idea, en serio: ... preparar cada vela tú misma.'::text,'debes'::text,'tienes que'::text,'deberías'::text,'Es tu propia idea, en serio: debes preparar cada vela tú misma.'::text),
(310820,34536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est ton idée à toi, franchement : tu ... préparer chaque bougie toi-même.'::text,'dois'::text,'dois'::text,'devrais'::text,'C''est ton idée à toi, franchement : tu dois préparer chaque bougie toi-même.'::text),
(310823,34536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi fikrin sonuçta, açıkçası: her mumu kendin ...'::text,'hazırlamalısın'::text,'hazırlamak zorundasın'::text,'hazırlamalısın'::text,'Kendi fikrin sonuçta, açıkçası: her mumu kendin hazırlamalısın.'::text),
(310824,34536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a saját ötleted, őszintén: minden gyertyát ... magad előkészítened.'::text,'kell'::text,'kell'::text,'kellene'::text,'Ez a saját ötleted, őszintén: minden gyertyát kell magad előkészítened.'::text),
(310827,34537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Raum ist dunkel, also ... sie zuerst die Kerzen vorbereiten.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Der Raum ist dunkel, also sollte sie zuerst die Kerzen vorbereiten.'::text),
(310831,34537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У кімнаті темно, тож вона ... спершу підготувати свічки.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'У кімнаті темно, тож вона мала б спершу підготувати свічки.'::text),
(310830,34537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sala está a oscuras, así que ... preparar primero las velas.'::text,'debería'::text,'debería'::text,'debería'::text,'La sala está a oscuras, así que debería preparar primero las velas.'::text),
(310829,34537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pièce est sombre, donc elle ... d''abord préparer les bougies.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'La pièce est sombre, donc elle devrait d''abord préparer les bougies.'::text),
(310832,34537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oda karanlık, bu yüzden önce mumları ...'::text,'hazırlamalı'::text,'hazırlamalı'::text,'hazırlamalı'::text,'Oda karanlık, bu yüzden önce mumları hazırlamalı.'::text),
(310833,34537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sötét van a szobában, ezért először a gyertyákat ... előkészítenie.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Sötét van a szobában, ezért először a gyertyákat kellene előkészítenie.'::text),
(310836,34538,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie deckt den Tisch, ... die Gäste sind noch nicht da.'::text,'aber'::text,'also'::text,'weil'::text,'Sie deckt den Tisch, aber die Gäste sind noch nicht da.'::text),
(310840,34538,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона готує стіл, ... гостей ще немає.'::text,'але'::text,'тому'::text,'бо'::text,'Вона готує стіл, але гостей ще немає.'::text),
(310839,34538,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prepara la mesa, ... los invitados todavía no han llegado.'::text,'pero'::text,'así que'::text,'porque'::text,'Prepara la mesa, pero los invitados todavía no han llegado.'::text),
(310838,34538,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle prépare la table, ... les invités ne sont pas encore là.'::text,'mais'::text,'donc'::text,'parce que'::text,'Elle prépare la table, mais les invités ne sont pas encore là.'::text),
(310841,34538,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masayı hazırlıyor ... misafirler henüz gelmedi.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Masayı hazırlıyor ama misafirler henüz gelmedi.'::text),
(310842,34538,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megteríti az asztalt, ... a vendégek még nincsenek itt.'::text,'de'::text,'ezért'::text,'mert'::text,'Megteríti az asztalt, de a vendégek még nincsenek itt.'::text),
(325884,36210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Total verrückt! Er ... jedes Wochenende eine neue Burg!'::text,'besucht'::text,'besuchen'::text,'besuchend'::text,'Total verrückt! Er besucht jedes Wochenende eine neue Burg!'::text),
(325888,36210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто божевілля! Він щовихідних ... новий замок!'::text,'відвідує'::text,'відвідувати'::text,'відвідуючи'::text,'Просто божевілля! Він щовихідних відвідує новий замок!'::text),
(325887,36210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Una locura total! ¡Cada fin de semana ... un castillo nuevo!'::text,'visita'::text,'visitar'::text,'visitando'::text,'¡Una locura total! ¡Cada fin de semana visita un castillo nuevo!'::text),
(325886,36210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Complètement fou ! Il ... un nouveau château chaque week-end !'::text,'visite'::text,'visiter'::text,'visitant'::text,'Complètement fou ! Il visite un nouveau château chaque week-end !'::text),
(325889,36210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamamen çılgınca! Her hafta sonu yeni bir kale ...!'::text,'gezer'::text,'gezmek'::text,'gezerek'::text,'Tamamen çılgınca! Her hafta sonu yeni bir kale gezer!'::text),
(325890,36210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen őrület! Minden hétvégén ... egy új várat!'::text,'meglátogat'::text,'meglátogatni'::text,'meglátogató'::text,'Teljesen őrület! Minden hétvégén meglátogat egy új várat!'::text),
(325902,36212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... besucht er? Alte Burgen auf Hügeln.'::text,'Was'::text,'Wer'::text,'Wann'::text,'Was besucht er? Alte Burgen auf Hügeln.'::text),
(325906,36212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він відвідує? Старі замки на пагорбах.'::text,'Що'::text,'Хто'::text,'Коли'::text,'Що він відвідує? Старі замки на пагорбах.'::text),
(325905,36212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... visita? Castillos antiguos en colinas.'::text,'Qué'::text,'Quién'::text,'Cuándo'::text,'¿Qué visita? Castillos antiguos en colinas.'::text),
(325904,36212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... visite-t-il ? De vieux châteaux sur des collines.'::text,'Que'::text,'Qui'::text,'Quand'::text,'Que visite-t-il ? De vieux châteaux sur des collines.'::text),
(325907,36212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... geziyor? Tepelerdeki eski kaleleri.'::text,'Neyi'::text,'Kim'::text,'Ne zaman'::text,'Neyi geziyor? Tepelerdeki eski kaleleri.'::text),
(325908,36212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... látogat meg? Régi várakat dombokon.'::text,'Mit'::text,'Ki'::text,'Mikor'::text,'Mit látogat meg? Régi várakat dombokon.'::text),
(325911,36213,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er diesen Sommer zehn Burgen besuchen ...'::text,'wird'::text,'werden'::text,'wird'::text,'Mädel, er hat mir erzählt, dass er diesen Sommer zehn Burgen besuchen wird.'::text),
(325915,36213,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... відвідати десять замків цього літа.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Подруго, він сказав мені, що збирається відвідати десять замків цього літа.'::text),
(325914,36213,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... visitar diez castillos este verano.'::text,'va a'::text,'van a'::text,'va a'::text,'Tía, me dijo que va a visitar diez castillos este verano.'::text),
(325913,36213,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''il ... visiter dix châteaux cet été.'::text,'va'::text,'vont'::text,'va'::text,'Ma belle, il m''a dit qu''il va visiter dix châteaux cet été.'::text),
(325916,36213,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dedi ki bu yaz on kale ...'::text,'gezecek'::text,'gezecekler'::text,'gezecek'::text,'Kızım, bana dedi ki bu yaz on kale gezecek.'::text),
(325917,36213,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy idén nyáron tíz várat ... meglátogatni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Csajszi, azt mondta, hogy idén nyáron tíz várat fog meglátogatni.'::text),
(325920,36214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, die Burg sieht krass aus. Okay, ich ... sie auch besuchen.'::text,'werde'::text,'werde'::text,NULL::text,'Nee Bro, die Burg sieht krass aus. Okay, ich werde sie auch besuchen.'::text),
(325924,36214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, той замок виглядає бомбезно. Окей, я теж ... його.'::text,'відвідаю'::text,'збираюся відвідати'::text,NULL::text,'Не, бро, той замок виглядає бомбезно. Окей, я теж відвідаю його.'::text),
(325923,36214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, ese castillo mola. Vale, yo también ... visitarlo.'::text,''::text,'voy a'::text,NULL::text,'Qué va, tío, ese castillo mola. Vale, yo también visitarlo.'::text),
(325922,36214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan frérot, ce château déchire. Ok, je ... le visiter aussi.'::text,''::text,'vais'::text,NULL::text,'Nan frérot, ce château déchire. Ok, je le visiter aussi.'::text),
(325925,36214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o kale efsane görünüyor. Tamam, onu ben de ...'::text,'gezeceğim'::text,'gezeceğim'::text,NULL::text,'Yok kanka, o kale efsane görünüyor. Tamam, onu ben de gezeceğim.'::text),
(325926,36214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, az a vár baromi jól néz ki. Oké, én is meg ... látogatni.'::text,'fogom'::text,'fogom'::text,NULL::text,'Nem, tesó, az a vár baromi jól néz ki. Oké, én is meg fogom látogatni.'::text),
(325929,36215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Burgregel: Besucher ... ein Ticket kaufen, um den Turm zu besichtigen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Burgregel: Besucher müssen ein Ticket kaufen, um den Turm zu besichtigen.'::text),
(325933,36215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило замку: відвідувачі ... купити квиток, щоб відвідати вежу.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Правило замку: відвідувачі мають купити квиток, щоб відвідати вежу.'::text),
(325932,36215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Norma del castillo: los visitantes ... comprar una entrada para visitar la torre.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Norma del castillo: los visitantes tienen que comprar una entrada para visitar la torre.'::text),
(325931,36215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle du château : les visiteurs ... acheter un billet pour visiter la tour.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Règle du château : les visiteurs doivent acheter un billet pour visiter la tour.'::text),
(325934,36215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kale kuralı: ziyaretçiler kuleyi gezmek için bilet ...'::text,'almak zorunda'::text,'almalı'::text,'almalı'::text,'Kale kuralı: ziyaretçiler kuleyi gezmek için bilet almak zorunda.'::text),
(325935,36215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várszabály: a látogatóknak jegyet ... venniük, hogy megnézhessék a tornyot.'::text,'kell'::text,'kell'::text,'kellene'::text,'Várszabály: a látogatóknak jegyet kell venniük, hogy megnézhessék a tornyot.'::text),
(325947,36217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hasst alte Burgen ganz offensichtlich, ... er hat heute drei besucht.'::text,'aber'::text,'also'::text,'weil'::text,'Er hasst alte Burgen ganz offensichtlich, aber er hat heute drei besucht.'::text),
(325951,36217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він явно ненавидить старі замки, ... сьогодні відвідав три.'::text,'але'::text,'тому'::text,'бо'::text,'Він явно ненавидить старі замки, але сьогодні відвідав три.'::text),
(325950,36217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que odia los castillos antiguos, ... hoy ha visitado tres.'::text,'pero'::text,'así que'::text,'porque'::text,'Está claro que odia los castillos antiguos, pero hoy ha visitado tres.'::text),
(325949,36217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il déteste clairement les vieux châteaux, ... il en a visité trois aujourd''hui.'::text,'mais'::text,'donc'::text,'parce que'::text,'Il déteste clairement les vieux châteaux, mais il en a visité trois aujourd''hui.'::text),
(325952,36217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski kalelerden resmen nefret ediyor ... bugün üç tane gezdi.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Eski kalelerden resmen nefret ediyor ama bugün üç tane gezdi.'::text),
(325953,36217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan utálja a régi várakat, ... ma hármat is meglátogatott.'::text,'de'::text,'ezért'::text,'mert'::text,'Nyilvánvalóan utálja a régi várakat, de ma hármat is meglátogatott.'::text),
(311385,34599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... er die Flasche mit einer schnellen Hand.'::text,'fing'::text,'fing'::text,'fängt'::text,'Mädel, angeblich fing er die Flasche mit einer schnellen Hand.'::text),
(311389,34599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... пляшку однією швидкою рукою.'::text,'спіймав'::text,'спіймав'::text,'ловить'::text,'Подруго, кажуть, він спіймав пляшку однією швидкою рукою.'::text),
(311388,34599,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, dicen que ... la botella con una mano rápida.'::text,'atrapó'::text,'atrapó'::text,'atrapa'::text,'Tía, dicen que atrapó la botella con una mano rápida.'::text),
(311387,34599,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... la bouteille d''une main rapide.'::text,'a attrapé'::text,'a attrapé'::text,'attrape'::text,'Ma belle, apparemment il a attrapé la bouteille d''une main rapide.'::text),
(311390,34599,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya şişeyi tek bir hızlı elle ...'::text,'yakaladı'::text,'yakaladı'::text,'yakalar'::text,'Kızım, güya şişeyi tek bir hızlı elle yakaladı.'::text),
(311391,34599,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag egyetlen gyors kézmozdulattal ... az üveget.'::text,'elkapta'::text,'elkapta'::text,'elkapja'::text,'Csajszi, állítólag egyetlen gyors kézmozdulattal elkapta az üveget.'::text),
(311394,34600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... gestern einen schnellen Fang.'::text,'machte'::text,'macht'::text,NULL::text,'Bestie, ich hab gehört, sie machte gestern einen schnellen Fang.'::text),
(311398,34600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула, що вона вчора ... швидкий перехват.'::text,'зробила'::text,'робить'::text,NULL::text,'Подружко, я чула, що вона вчора зробила швидкий перехват.'::text),
(311397,34600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me han dicho que ayer ... una parada rápida.'::text,'hizo'::text,'hace'::text,NULL::text,'Amiga, me han dicho que ayer hizo una parada rápida.'::text),
(311396,34600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma chérie, j''ai entendu dire qu''hier elle ... une réception rapide.'::text,'a fait'::text,'fait'::text,NULL::text,'Ma chérie, j''ai entendu dire qu''hier elle a fait une réception rapide.'::text),
(311399,34600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, duyduğuma göre dün hızlı bir yakalama ...'::text,'yaptı'::text,'yapar'::text,NULL::text,'Kankam, duyduğuma göre dün hızlı bir yakalama yaptı.'::text),
(311400,34600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barátnőm, azt hallottam, hogy tegnap ... egy gyors elkapást.'::text,'bemutatott'::text,'bemutat'::text,NULL::text,'Barátnőm, azt hallottam, hogy tegnap bemutatott egy gyors elkapást.'::text),
(311412,34602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge spielt normalerweise Fußball, aber jetzt ... er einen schnellen Wasserball.'::text,'stoppt'::text,'stoppt'::text,NULL::text,'Der Junge spielt normalerweise Fußball, aber jetzt stoppt er einen schnellen Wasserball.'::text),
(311416,34602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець зазвичай грає у футбол, але зараз він ... швидкий пляжний м''яч.'::text,'зупиняє'::text,'зупиняє'::text,NULL::text,'Хлопець зазвичай грає у футбол, але зараз він зупиняє швидкий пляжний м''яч.'::text),
(311415,34602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico suele jugar al fútbol, pero ahora ... una pelota de playa rápida.'::text,'está parando'::text,'para'::text,NULL::text,'El chico suele jugar al fútbol, pero ahora está parando una pelota de playa rápida.'::text),
(311414,34602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon joue d''habitude au foot, mais là il ... un ballon de plage rapide.'::text,'est en train d''arrêter'::text,'arrête'::text,NULL::text,'Le garçon joue d''habitude au foot, mais là il est en train d''arrêter un ballon de plage rapide.'::text),
(311417,34602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk genelde futbol oynar ama şimdi hızlı bir plaj topunu ...'::text,'durduruyor'::text,'durdurur'::text,NULL::text,'Çocuk genelde futbol oynar ama şimdi hızlı bir plaj topunu durduruyor.'::text),
(311418,34602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú általában focizik, de most ... egy gyors strandlabdát.'::text,'megállít'::text,'megállít'::text,NULL::text,'A fiú általában focizik, de most megállít egy gyors strandlabdát.'::text),
(311421,34603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist schnell, also ... er die fallende Flasche fangen.'::text,'wird'::text,'ist'::text,'war'::text,'Er ist schnell, also wird er die fallende Flasche fangen.'::text),
(311425,34603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він швидкий, тож він ... падаючу пляшку.'::text,'спіймає'::text,'є'::text,'був'::text,'Він швидкий, тож він спіймає падаючу пляшку.'::text),
(311424,34603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es rápido, así que ... atrapar la botella que cae.'::text,''::text,'está'::text,'estaba'::text,'Es rápido, así que atrapar la botella que cae.'::text),
(311423,34603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est rapide, donc il ... attraper la bouteille qui tombe.'::text,''::text,'est'::text,'était'::text,'Il est rapide, donc il attraper la bouteille qui tombe.'::text),
(311426,34603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hızlı, bu yüzden düşen şişeyi ...'::text,'yakalayacak'::text,NULL::text,'idi'::text,'Hızlı, bu yüzden düşen şişeyi yakalayacak.'::text),
(311427,34603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyors, ezért el ... kapni a leeső üveget.'::text,'fogja'::text,'van'::text,'volt'::text,'Gyors, ezért el fogja kapni a leeső üveget.'::text),
(311430,34604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe abgewendet! Sie war ... als die fallende Wassermelone!'::text,'schneller'::text,'schneller'::text,'am schnellsten'::text,'Katastrophe abgewendet! Sie war schneller als die fallende Wassermelone!'::text),
(311434,34604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофу відвернуто! Вона була ... за падаючий кавун!'::text,'швидша'::text,'більш швидка'::text,'найшвидша'::text,'Катастрофу відвернуто! Вона була швидша за падаючий кавун!'::text),
(311433,34604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre evitado! ¡Fue ... que la sandía que caía!'::text,'más rápida'::text,'más rápida'::text,'la más rápida'::text,'¡Desastre evitado! ¡Fue más rápida que la sandía que caía!'::text),
(311432,34604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe évitée ! Elle a été ... que la pastèque qui tombait !'::text,'plus rapide'::text,'plus rapide'::text,'la plus rapide'::text,'Catastrophe évitée ! Elle a été plus rapide que la pastèque qui tombait !'::text),
(311435,34604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket önlendi! Düşen karpuzdan ... davrandı!'::text,'daha hızlı'::text,'daha hızlı'::text,'en hızlı'::text,'Felaket önlendi! Düşen karpuzdan daha hızlı davrandı!'::text),
(311436,34604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa elhárítva! ... volt, mint a leeső dinnye!'::text,'Gyorsabb'::text,'Gyorsabb'::text,'Leggyorsabb'::text,'Katasztrófa elhárítva! Gyorsabb volt, mint a leeső dinnye!'::text),
(311439,34605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Der schnelle Torwart springt ... und hält den Ball!'::text,'mutig'::text,'mutig'::text,'Mut'::text,'Albtraum! Der schnelle Torwart springt mutig und hält den Ball!'::text),
(311443,34605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Швидкий воротар ... кидається й ловить м''яч!'::text,'хоробро'::text,'хоробрий'::text,'хоробрість'::text,'Жах! Швидкий воротар хоробро кидається й ловить м''яч!'::text),
(311442,34605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El portero rápido se lanza ... y para el balón!'::text,'valientemente'::text,'valiente'::text,'valentía'::text,'¡Pesadilla! ¡El portero rápido se lanza valientemente y para el balón!'::text),
(311441,34605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le gardien rapide plonge ... et arrête le ballon !'::text,'courageusement'::text,'courageux'::text,'courage'::text,'Cauchemar ! Le gardien rapide plonge courageusement et arrête le ballon !'::text),
(311444,34605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Hızlı kaleci ... atlıyor ve topu kurtarıyor!'::text,'cesurca'::text,'cesur'::text,'cesaret'::text,'Kâbus! Hızlı kaleci cesurca atlıyor ve topu kurtarıyor!'::text),
(311445,34605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A gyors kapus ... vetődik, és hárítja a labdát!'::text,'bátran'::text,'bátor'::text,'bátorság'::text,'Rémálom! A gyors kapus bátran vetődik, és hárítja a labdát!'::text),
(327756,36418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Jahr ... sie sich dasselbe! Das Schlimmste!'::text,'wünscht'::text,'wünschen'::text,'wünscht'::text,'Jedes Jahr wünscht sie sich dasselbe! Das Schlimmste!'::text),
(327760,36418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щороку вона ... одного й того самого! Найгірше!'::text,'бажає'::text,'бажати'::text,'бажає'::text,'Щороку вона бажає одного й того самого! Найгірше!'::text),
(327759,36418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada año ... lo mismo! ¡Lo peor!'::text,'desea'::text,'desear'::text,'desea'::text,'¡Cada año desea lo mismo! ¡Lo peor!'::text),
(327758,36418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque année, elle ... la même chose ! Le pire !'::text,'souhaite'::text,'souhaiter'::text,'souhaite'::text,'Chaque année, elle souhaite la même chose ! Le pire !'::text),
(327761,36418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yıl aynı şeyi ...! En kötüsü!'::text,'diler'::text,'dilemek'::text,'diler'::text,'Her yıl aynı şeyi diler! En kötüsü!'::text),
(327762,36418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden évben ugyanazt ...! A legrosszabb!'::text,'kívánja'::text,'kívánni'::text,'kívánja'::text,'Minden évben ugyanazt kívánja! A legrosszabb!'::text),
(327765,36419,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich mit geschlossenen Augen etwas wünschen.'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann sich mit geschlossenen Augen etwas wünschen.'::text),
(327769,36419,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... загадати бажання із заплющеними очима.'::text,'може'::text,'може'::text,'є'::text,'Вона може загадати бажання із заплющеними очима.'::text),
(327768,36419,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con los ojos cerrados ... pedir un deseo.'::text,'puede'::text,'puede'::text,'está'::text,'Con los ojos cerrados puede pedir un deseo.'::text),
(327767,36419,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... faire un vœu les yeux fermés.'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut faire un vœu les yeux fermés.'::text),
(327770,36419,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri kapalıyken bir dilek ...'::text,'tutabilir'::text,'tutabilir'::text,NULL::text,'Gözleri kapalıyken bir dilek tutabilir.'::text),
(327771,36419,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csukott szemmel ... valamit.'::text,'kívánhat'::text,'kívánhat'::text,'van'::text,'Csukott szemmel kívánhat valamit.'::text),
(327783,36421,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine sehr ruhige Party, klar. Sie ... sich nächstes Jahr mehr Gäste wünschen.'::text,'wird'::text,'wird'::text,'wird'::text,'Eine sehr ruhige Party, klar. Sie wird sich nächstes Jahr mehr Gäste wünschen.'::text),
(327787,36421,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже тиха вечірка, очевидно. Вона ... собі більше гостей наступного року.'::text,'збирається побажати'::text,'збирається побажати'::text,'побажає'::text,'Дуже тиха вечірка, очевидно. Вона збирається побажати собі більше гостей наступного року.'::text),
(327786,36421,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una fiesta muy tranquila, obviamente. ... pedir más invitados el año que viene.'::text,'Va a'::text,'Va a'::text,NULL::text,'Una fiesta muy tranquila, obviamente. Va a pedir más invitados el año que viene.'::text),
(327785,36421,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fête très calme, évidemment. Elle ... souhaiter plus d''invités l''an prochain.'::text,'va'::text,'va'::text,NULL::text,'Une fête très calme, évidemment. Elle va souhaiter plus d''invités l''an prochain.'::text),
(327788,36421,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sessiz bir parti, belli ki. Seneye daha fazla misafir ...'::text,'dileyecek'::text,'dileyecek'::text,'dileyecek'::text,'Çok sessiz bir parti, belli ki. Seneye daha fazla misafir dileyecek.'::text),
(327789,36421,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon csendes buli, nyilván. Jövőre több vendéget ... kívánni.'::text,'fog'::text,'fog'::text,'fog'::text,'Nagyon csendes buli, nyilván. Jövőre több vendéget fog kívánni.'::text),
(327792,36422,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ihre Augen sind zu, sie ... sich was wünschen, echt.'::text,'wird'::text,'wird'::text,NULL::text,'Bro, ihre Augen sind zu, sie wird sich was wünschen, echt.'::text),
(327796,36422,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у неї заплющені очі, вона ... бажання, реально.'::text,'збирається загадати'::text,'загадає'::text,NULL::text,'Бро, у неї заплющені очі, вона збирається загадати бажання, реально.'::text),
(327795,36422,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tiene los ojos cerrados, ... pedir un deseo, en serio.'::text,'va a'::text,NULL::text,NULL::text,'Tío, tiene los ojos cerrados, va a pedir un deseo, en serio.'::text),
(327794,36422,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle a les yeux fermés, elle ... faire un vœu, sérieux.'::text,'va'::text,NULL::text,NULL::text,'Frérot, elle a les yeux fermés, elle va faire un vœu, sérieux.'::text),
(327797,36422,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gözleri kapalı, bir dilek ..., cidden.'::text,'tutacak'::text,'tutacak'::text,NULL::text,'Kanka, gözleri kapalı, bir dilek tutacak, cidden.'::text),
(327798,36422,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, csukva van a szeme, ... kívánni valamit, komolyan.'::text,'fog'::text,'fog'::text,NULL::text,'Tesó, csukva van a szeme, fog kívánni valamit, komolyan.'::text),
(327810,36424,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: 1 Wunsch pro Jahr, also ... sie sich mit Bedacht etwas wünschen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Budget: 1 Wunsch pro Jahr, also sollte sie sich mit Bedacht etwas wünschen.'::text),
(327814,36424,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: 1 бажання на рік, тож вона ... загадувати його обережно.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Бюджет: 1 бажання на рік, тож вона мала б загадувати його обережно.'::text),
(327813,36424,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: 1 deseo al año, así que ... pedirlo con cuidado.'::text,'debería'::text,'debería'::text,'debería'::text,'Presupuesto: 1 deseo al año, así que debería pedirlo con cuidado.'::text),
(327812,36424,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : 1 vœu par an, donc elle ... bien choisir son vœu.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Budget : 1 vœu par an, donc elle devrait bien choisir son vœu.'::text),
(327815,36424,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: yılda 1 dilek, bu yüzden dikkatli ...'::text,'dilemeli'::text,'dilemeli'::text,'dilemeli'::text,'Bütçe: yılda 1 dilek, bu yüzden dikkatli dilemeli.'::text),
(327816,36424,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: évi 1 kívánság, ezért óvatosan ... kívánnia.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Költségvetés: évi 1 kívánság, ezért óvatosan kellene kívánnia.'::text),
(327819,36425,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie blies die Kerzen aus, ... die Kerzen für ihren Wunsch waren.'::text,'weil'::text,'aber'::text,'oder'::text,'Sie blies die Kerzen aus, weil die Kerzen für ihren Wunsch waren.'::text),
(327823,36425,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона задула свічки, ... свічки були для її бажання.'::text,'бо'::text,'але'::text,'або'::text,'Вона задула свічки, бо свічки були для її бажання.'::text),
(327822,36425,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sopló las velas ... las velas eran para su deseo.'::text,'porque'::text,'pero'::text,'o'::text,'Sopló las velas porque las velas eran para su deseo.'::text),
(327821,36425,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a soufflé les bougies ... les bougies étaient pour son vœu.'::text,'parce que'::text,'mais'::text,'ou'::text,'Elle a soufflé les bougies parce que les bougies étaient pour son vœu.'::text),
(327824,36425,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mumları üfledi ... mumlar onun dileği içindi.'::text,'çünkü'::text,'ama'::text,'veya'::text,'Mumları üfledi çünkü mumlar onun dileği içindi.'::text),
(327825,36425,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elfújta a gyertyákat, ... a gyertyák a kívánságához kellettek.'::text,'mert'::text,'de'::text,'vagy'::text,'Elfújta a gyertyákat, mert a gyertyák a kívánságához kellettek.'::text),
(320556,35618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Büro ... Luftballons für den Erfolg des Teams.'::text,'hat'::text,'haben'::text,'ist'::text,'Das Büro hat Luftballons für den Erfolg des Teams.'::text),
(320560,35618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіс ... повітряні кульки на честь успіху команди.'::text,'має'::text,'мати'::text,'є'::text,'Офіс має повітряні кульки на честь успіху команди.'::text),
(320559,35618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La oficina ... globos por el éxito del equipo.'::text,'tiene'::text,'tienen'::text,'está'::text,'La oficina tiene globos por el éxito del equipo.'::text),
(320558,35618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bureau ... des ballons pour le succès de l''équipe.'::text,'a'::text,'ont'::text,'est'::text,'Le bureau a des ballons pour le succès de l''équipe.'::text),
(320561,35618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofiste takımın başarısı için balonlar ...'::text,'var'::text,'var'::text,NULL::text,'Ofiste takımın başarısı için balonlar var.'::text),
(320562,35618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodában lufik ... a csapat sikere miatt.'::text,'vannak'::text,'vannak'::text,'vannak'::text,'Az irodában lufik vannak a csapat sikere miatt.'::text),
(320565,35619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team hat dieses Jahr zwei große ...'::text,'Erfolge'::text,'Erfolg'::text,'Erfolge'::text,'Das Team hat dieses Jahr zwei große Erfolge.'::text),
(320569,35619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього року в команди два великі ...'::text,'успіхи'::text,'успіх'::text,'успіхи'::text,'Цього року в команди два великі успіхи.'::text),
(320568,35619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este año el equipo tiene dos grandes ...'::text,'éxitos'::text,'éxito'::text,'éxitos'::text,'Este año el equipo tiene dos grandes éxitos.'::text),
