(303656,33740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans l''entrepôt, il vérifie deux ...'::text,'listes.'::text,'liste.'::text,'listes.'::text,'Dans l''entrepôt, il vérifie deux listes.'::text),
(303659,33740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depoda iki ... kontrol ediyor.'::text,'liste'::text,'liste'::text,'listeler'::text,'Depoda iki liste kontrol ediyor.'::text),
(303660,33740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A raktárban két ... ellenőriz.'::text,'listát'::text,'listát'::text,'listát'::text,'A raktárban két listát ellenőriz.'::text),
(303672,33742,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hakt ... in seiner Hand ab.'::text,'diese Liste'::text,'diese Listen'::text,'jene Listen'::text,'Er hakt diese Liste in seiner Hand ab.'::text),
(303676,33742,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він позначає пункти на ... в руці.'::text,'цьому списку'::text,'цьому списку'::text,'тому списку'::text,'Він позначає пункти на цьому списку в руці.'::text),
(303675,33742,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Marca ... que tiene en la mano.'::text,'esta lista'::text,'estas listas'::text,'esas listas'::text,'Marca esta lista que tiene en la mano.'::text),
(303674,33742,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il coche ... qu''il tient à la main.'::text,'cette liste'::text,'ces listes'::text,'ces listes'::text,'Il coche cette liste qu''il tient à la main.'::text),
(303677,33742,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elindeki ... işaretliyor.'::text,'bu listeyi'::text,'bu listeyi'::text,'şu listeyi'::text,'Elindeki bu listeyi işaretliyor.'::text),
(303678,33742,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kipipálja ... a kezében.'::text,'ezt a listát'::text,'ezeket a listákat'::text,'azokat a listákat'::text,'Kipipálja ezt a listát a kezében.'::text),
(303681,33743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Er verliert ... Liste im Lager! Katastrophe!'::text,'seine'::text,'ihre'::text,'seine'::text,'Nein! Er verliert seine Liste im Lager! Katastrophe!'::text),
(303685,33743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Він губить ... список на складі! Катастрофа!'::text,'свій'::text,'свій'::text,'свій'::text,'Ні! Він губить свій список на складі! Катастрофа!'::text),
(303684,33743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Pierde ... lista en el almacén! ¡Desastre!'::text,'su'::text,'su'::text,'su'::text,'¡No! ¡Pierde su lista en el almacén! ¡Desastre!'::text),
(303683,33743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Il perd ... liste dans l''entrepôt ! Catastrophe !'::text,'sa'::text,'sa'::text,'sa'::text,'Non ! Il perd sa liste dans l''entrepôt ! Catastrophe !'::text),
(303686,33743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Depoda ... listesini kaybediyor! Felaket!'::text,'onun'::text,'onun'::text,'onun'::text,'Hayır! Depoda onun listesini kaybediyor! Felaket!'::text),
(303687,33743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Elveszíti a ... a raktárban! Katasztrófa!'::text,'listáját'::text,'listáját'::text,'listáját'::text,'Ne! Elveszíti a listáját a raktárban! Katasztrófa!'::text),
(303699,33745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, dass auf seiner Liste ... Kartons stehen.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Hör zu, er hat mir gesagt, dass auf seiner Liste viele Kartons stehen.'::text),
(303703,33745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що в його списку ... коробок.'::text,'багато'::text,'багато'::text,'трохи'::text,'Слухай, він сказав мені, що в його списку багато коробок.'::text),
(303702,33745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que en su lista hay ... cajas.'::text,'muchas'::text,'mucha'::text,'un poco de'::text,'Oye, me dijo que en su lista hay muchas cajas.'::text),
(303701,33745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il y a ... cartons sur sa liste.'::text,'beaucoup de'::text,'beaucoup de'::text,'un peu de'::text,'Écoute, il m''a dit qu''il y a beaucoup de cartons sur sa liste.'::text),
(303704,33745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana listesinde ... koli olduğunu söyledi.'::text,'çok'::text,'çok'::text,'biraz'::text,'Dinle, bana listesinde çok koli olduğunu söyledi.'::text),
(303705,33745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy ... doboz van a listáján.'::text,'sok'::text,'sok'::text,'egy kis'::text,'Figyelj, azt mondta, hogy sok doboz van a listáján.'::text),
(303708,33746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, angeblich ... fünfzig Kartons auf seiner Liste.'::text,'sind'::text,'ist'::text,'sein'::text,'Rate mal, angeblich sind fünfzig Kartons auf seiner Liste.'::text),
(303712,33746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, кажуть, у його списку ... п''ятдесят коробок.'::text,'є'::text,'є'::text,'бути'::text,'Уяви, кажуть, у його списку є п''ятдесят коробок.'::text),
(303711,33746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué: dicen que en su lista ... cincuenta cajas.'::text,'hay'::text,'hay'::text,'hay'::text,'Adivina qué: dicen que en su lista hay cincuenta cajas.'::text),
(303710,33746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment ... cinquante cartons sur sa liste.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Devine quoi, apparemment il y a cinquante cartons sur sa liste.'::text),
(303713,33746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, güya listesinde elli koli ...'::text,'var'::text,'var'::text,'olmak'::text,'Tahmin et ne oldu, güya listesinde elli koli var.'::text),
(303714,33746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag ötven doboz ... a listáján.'::text,'van'::text,'van'::text,'lenni'::text,'Képzeld, állítólag ötven doboz van a listáján.'::text),
(320637,35627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... einen Koffer mit langem Griff.'::text,'hat'::text,'haben'::text,'ist'::text,'Die Frau hat einen Koffer mit langem Griff.'::text),
(320641,35627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... валізу з довгою ручкою.'::text,'має'::text,'мати'::text,'є'::text,'Жінка має валізу з довгою ручкою.'::text),
(320640,35627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... una maleta con un asa larga.'::text,'tiene'::text,'tienen'::text,'está'::text,'La mujer tiene una maleta con un asa larga.'::text),
(320639,35627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... une valise avec une longue poignée.'::text,'a'::text,'ont'::text,'est'::text,'La femme a une valise avec une longue poignée.'::text),
(320642,35627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadının uzun saplı bir bavulu ...'::text,'var'::text,'var'::text,NULL::text,'Kadının uzun saplı bir bavulu var.'::text),
(320643,35627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nőnek ... egy hosszú fogantyús bőröndje.'::text,'van'::text,'van'::text,'van'::text,'A nőnek van egy hosszú fogantyús bőröndje.'::text),
(320646,35628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat einen Koffer, nicht zwei ...'::text,'Koffer'::text,'Koffer'::text,'Koffer'::text,'Sie hat einen Koffer, nicht zwei Koffer.'::text),
(320650,35628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї одна валіза, а не дві ...'::text,'валізи'::text,'валіза'::text,'валізи'::text,'У неї одна валіза, а не дві валізи.'::text),
(320649,35628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene una maleta, no dos ...'::text,'maletas'::text,'maleta'::text,'maletas'::text,'Tiene una maleta, no dos maletas.'::text),
(320648,35628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a une valise, pas deux ...'::text,'valises'::text,'valise'::text,'valises'::text,'Elle a une valise, pas deux valises.'::text),
(320651,35628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir bavulu var, iki ... değil.'::text,'bavul'::text,'bavul'::text,'bavullar'::text,'Onun bir bavulu var, iki bavul değil.'::text),
(320652,35628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy bőröndje van, nem két ...'::text,'bőrönd'::text,'bőrönd'::text,'bőrönd'::text,'Egy bőröndje van, nem két bőrönd.'::text),
(320664,35630,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ist ... dort drüben mein Koffer? Der schlimmste Tag überhaupt!'::text,'das'::text,'dies'::text,'jene'::text,'Ist das dort drüben mein Koffer? Der schlimmste Tag überhaupt!'::text),
(320668,35630,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... он там моя валіза? Найгірший день у житті!'::text,'То'::text,'Це'::text,'Ті'::text,'То он там моя валіза? Найгірший день у житті!'::text),
(320667,35630,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... de allí es mi maleta? ¡El peor día de mi vida!'::text,'Esa'::text,'Esta'::text,'Esas'::text,'¿Esa de allí es mi maleta? ¡El peor día de mi vida!'::text),
(320666,35630,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... là-bas, c''est ma valise ? Le pire jour de ma vie !'::text,'Celle'::text,'Celle-ci'::text,'Celles'::text,'Celle là-bas, c''est ma valise ? Le pire jour de ma vie !'::text),
(320669,35630,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oradaki ... benim bavulum mu? Hayatımın en kötü günü!'::text,'şu'::text,'bu'::text,'şunlar'::text,'Oradaki şu benim bavulum mu? Hayatımın en kötü günü!'::text),
(320670,35630,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ott az én bőröndöm? Minden idők legrosszabb napja!'::text,'Az'::text,'Ez'::text,'Azok'::text,'Az ott az én bőröndöm? Minden idők legrosszabb napja!'::text),
(320673,35631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat einen Koffer und ... Pass.'::text,'einen'::text,'ersten'::text,'einmal'::text,'Sie hat einen Koffer und einen Pass.'::text),
(320677,35631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї одна валіза й ... паспорт.'::text,'один'::text,'перший'::text,'один раз'::text,'У неї одна валіза й один паспорт.'::text),
(320676,35631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene una maleta y ... pasaporte.'::text,'un'::text,'primer'::text,'una vez'::text,'Tiene una maleta y un pasaporte.'::text),
(320675,35631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a une valise et ... passeport.'::text,'un'::text,'premier'::text,'une fois'::text,'Elle a une valise et un passeport.'::text),
(320678,35631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun bir bavulu ve ... pasaportu var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Onun bir bavulu ve bir pasaportu var.'::text),
(320679,35631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy bőröndje és ... útlevele.'::text,'egy'::text,'első'::text,'egyszer'::text,'Van egy bőröndje és egy útlevele.'::text),
(320682,35632,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ist in ihrem Koffer so viel ...'::text,'Kleidung'::text,'Klamotten'::text,'Kleider'::text,'Hör zu, angeblich ist in ihrem Koffer so viel Kleidung.'::text),
(320686,35632,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, у її валізі стільки ...'::text,'одягу'::text,'одягу'::text,'суконь'::text,'Слухай, кажуть, у її валізі стільки одягу.'::text),
(320685,35632,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dicen que su maleta lleva tanta ...'::text,'ropa'::text,'ropa'::text,'vestidos'::text,'Oye, dicen que su maleta lleva tanta ropa.'::text),
(320684,35632,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment sa valise contient tellement de ...'::text,'vêtements'::text,'vêtements'::text,'robes'::text,'Écoute, apparemment sa valise contient tellement de vêtements.'::text),
(320687,35632,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya bavulunun içinde o kadar çok ... var.'::text,'giysi'::text,'kıyafetler'::text,'elbiseler'::text,'Dinle, güya bavulunun içinde o kadar çok giysi var.'::text),
(320688,35632,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag annyi ... van a bőröndjében.'::text,'ruhanemű'::text,'ruha'::text,'ruha'::text,'Figyelj, állítólag annyi ruhanemű van a bőröndjében.'::text),
(320691,35633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie hat eigentlich noch ... Zeit, Koffer fertig.'::text,'etwas'::text,'viele'::text,'ein paar'::text,'Yo, sie hat eigentlich noch etwas Zeit, Koffer fertig.'::text),
(320695,35633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, у неї ще є ... часу, валіза готова.'::text,'трохи'::text,'багато'::text,'кілька'::text,'Йо, у неї ще є трохи часу, валіза готова.'::text),
(320694,35633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, en plan le queda ... tiempo, maleta lista.'::text,'algo de'::text,'muchos'::text,'unos pocos'::text,'Oye, en plan le queda algo de tiempo, maleta lista.'::text),
(320693,35633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, en vrai il lui reste ... temps, valise prête.'::text,'du'::text,'beaucoup de'::text,'quelques'::text,'Yo, en vrai il lui reste du temps, valise prête.'::text),
(320696,35633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, aslında daha ... vakti var, bavul hazır.'::text,'biraz'::text,'çok'::text,'birkaç'::text,'Kanka, aslında daha biraz vakti var, bavul hazır.'::text),
(320697,35633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, lényegében van még ... ideje, a bőrönd kész.'::text,'némi'::text,'sok'::text,'pár'::text,'Figyu, lényegében van még némi ideje, a bőrönd kész.'::text),
(327441,36383,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nur ein schneller Läufer ... eine Medaille gewinnen.'::text,'kann'::text,'ist'::text,'kann'::text,'Nur ein schneller Läufer kann eine Medaille gewinnen.'::text),
(327445,36383,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише швидкий бігун ... виграти медаль.'::text,'може'::text,'є'::text,'може'::text,'Лише швидкий бігун може виграти медаль.'::text),
(327444,36383,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo un corredor rápido ... ganar una medalla.'::text,'puede'::text,'está'::text,'puede'::text,'Solo un corredor rápido puede ganar una medalla.'::text),
(327443,36383,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seul un coureur rapide ... gagner une médaille.'::text,'peut'::text,'est'::text,'peut'::text,'Seul un coureur rapide peut gagner une médaille.'::text),
(327446,36383,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece hızlı bir koşucu madalya ...'::text,'kazanabilir'::text,NULL::text,'kazanabilir'::text,'Sadece hızlı bir koşucu madalya kazanabilir.'::text),
(327447,36383,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak egy gyors futó ... érmet.'::text,'nyerhet'::text,'van'::text,'nyerhet'::text,'Csak egy gyors futó nyerhet érmet.'::text),
(327450,36384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... das Rennen, und die Medaille ist irgendwie ikonisch.'::text,'gewann'::text,'gewann'::text,'gewinnt'::text,'Bro, er gewann das Rennen, und die Medaille ist irgendwie ikonisch.'::text),
(327454,36384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... забіг, і медаль реально іконічна.'::text,'виграв'::text,'виграв'::text,'виграє'::text,'Бро, він виграв забіг, і медаль реально іконічна.'::text),
(327453,36384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... la carrera y la medalla es bastante icónica.'::text,'ganó'::text,'ganó'::text,'gana'::text,'Tío, ganó la carrera y la medalla es bastante icónica.'::text),
(327452,36384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... la course et la médaille est plutôt iconique.'::text,'a gagné'::text,'a gagné'::text,'gagne'::text,'Frérot, il a gagné la course et la médaille est plutôt iconique.'::text),
(327455,36384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarışı ... ve madalya resmen ikonik.'::text,'kazandı'::text,'kazandı'::text,'kazanır'::text,'Kanka, yarışı kazandı ve madalya resmen ikonik.'::text),
(327456,36384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... a versenyt, és az érem elég ikonikus.'::text,'megnyerte'::text,'megnyerte'::text,'megnyeri'::text,'Tesó, megnyerte a versenyt, és az érem elég ikonikus.'::text),
(327459,36385,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er verliert normalerweise Rennen, aber gestern ... er eine Medaille, echt.'::text,'gewann'::text,'gewinnt'::text,NULL::text,'Alter, er verliert normalerweise Rennen, aber gestern gewann er eine Medaille, echt.'::text),
(327463,36385,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він зазвичай програє забіги, але вчора ... медаль, реально.'::text,'виграв'::text,'виграє'::text,NULL::text,'Чувак, він зазвичай програє забіги, але вчора виграв медаль, реально.'::text),
(327462,36385,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, normalmente pierde las carreras, pero ayer ... una medalla, en serio.'::text,'ganó'::text,'gana'::text,NULL::text,'Tío, normalmente pierde las carreras, pero ayer ganó una medalla, en serio.'::text),
(327461,36385,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, d''habitude il perd les courses, mais hier il ... une médaille, sérieux.'::text,'a gagné'::text,'gagne'::text,NULL::text,'Mec, d''habitude il perd les courses, mais hier il a gagné une médaille, sérieux.'::text),
(327464,36385,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, genelde yarışları kaybeder ama dün madalya ..., cidden.'::text,'kazandı'::text,'kazanır'::text,NULL::text,'Kanka, genelde yarışları kaybeder ama dün madalya kazandı, cidden.'::text),
(327465,36385,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, általában elveszíti a versenyeket, de tegnap ... egy érmet, komolyan.'::text,'nyert'::text,'nyer'::text,NULL::text,'Tesó, általában elveszíti a versenyeket, de tegnap nyert egy érmet, komolyan.'::text),
(327477,36387,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gewinnt oft Rennen, und gerade ... er noch eine Medaille.'::text,'gewinnt'::text,'gewinnt'::text,NULL::text,'Er gewinnt oft Rennen, und gerade gewinnt er noch eine Medaille.'::text),
(327481,36387,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він часто виграє забіги, а саме зараз ... ще одну медаль.'::text,'виграє'::text,'виграє'::text,NULL::text,'Він часто виграє забіги, а саме зараз виграє ще одну медаль.'::text),
(327480,36387,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gana carreras a menudo, y ahora mismo ... otra medalla.'::text,'está ganando'::text,'gana'::text,NULL::text,'Gana carreras a menudo, y ahora mismo está ganando otra medalla.'::text),
(327479,36387,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il gagne souvent des courses, et en ce moment il ... une autre médaille.'::text,'est en train de gagner'::text,'gagne'::text,NULL::text,'Il gagne souvent des courses, et en ce moment il est en train de gagner une autre médaille.'::text),
(327482,36387,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sık sık yarış kazanır ve şu an bir madalya daha ...'::text,'kazanıyor'::text,'kazanır'::text,NULL::text,'Sık sık yarış kazanır ve şu an bir madalya daha kazanıyor.'::text),
(327483,36387,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyakran nyer versenyeket, és most épp ... még egy érmet.'::text,'nyer'::text,'nyer'::text,NULL::text,'Gyakran nyer versenyeket, és most épp nyer még egy érmet.'::text),
(327486,36388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will wieder gewinnen, also ... er jede Woche trainieren.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Er will wieder gewinnen, also sollte er jede Woche trainieren.'::text),
(327490,36388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче знову виграти, тож ... тренуватися щотижня.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Він хоче знову виграти, тож мав би тренуватися щотижня.'::text),
(327489,36388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quiere volver a ganar, así que ... entrenar cada semana.'::text,'debería'::text,'debería'::text,'debería'::text,'Quiere volver a ganar, así que debería entrenar cada semana.'::text),
(327488,36388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut gagner encore, donc il ... s''entraîner chaque semaine.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Il veut gagner encore, donc il devrait s''entraîner chaque semaine.'::text),
(327491,36388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yine kazanmak istiyor, bu yüzden her hafta antrenman ...'::text,'yapmalı'::text,'yapmalı'::text,'yapmalı'::text,'Yine kazanmak istiyor, bu yüzden her hafta antrenman yapmalı.'::text),
(327492,36388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Újra nyerni akar, ezért minden héten ... edzenie.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Újra nyerni akar, ezért minden héten kellene edzenie.'::text),
(327495,36389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du hast die Medaille gewonnen, ... du so hart trainiert hast.'::text,'weil'::text,'aber'::text,'also'::text,'Respekt, du hast die Medaille gewonnen, weil du so hart trainiert hast.'::text),
(327499,36389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти виграв медаль, ... так наполегливо тренувався.'::text,'бо'::text,'але'::text,'тому'::text,'Респект, ти виграв медаль, бо так наполегливо тренувався.'::text),
(327498,36389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, ganaste la medalla ... entrenaste muchísimo.'::text,'porque'::text,'pero'::text,'así que'::text,'Respeto, ganaste la medalla porque entrenaste muchísimo.'::text),
(327497,36389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu as gagné la médaille ... tu t''es entraîné si dur.'::text,'parce que'::text,'mais'::text,'donc'::text,'Respect, tu as gagné la médaille parce que tu t''es entraîné si dur.'::text),
(327500,36389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygılar, madalyayı kazandın ... çok sıkı çalıştın.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Saygılar, madalyayı kazandın çünkü çok sıkı çalıştın.'::text),
(327501,36389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le a kalappal, megnyerted az érmet, ... olyan keményen edzettél.'::text,'mert'::text,'de'::text,'ezért'::text,'Le a kalappal, megnyerted az érmet, mert olyan keményen edzettél.'::text),
(323643,35961,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... eine coole Rundreise durch China.'::text,'hast'::text,'hat'::text,'bist'::text,'Ehrlich gesagt, du hast eine coole Rundreise durch China.'::text),
(323647,35961,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти ... круту подорож Китаєм.'::text,'маєш'::text,'має'::text,'є'::text,'Не брехатиму, ти маєш круту подорож Китаєм.'::text),
(323646,35961,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... un viaje guay por China.'::text,'tienes'::text,'tiene'::text,'estás'::text,'No te voy a mentir, tienes un viaje guay por China.'::text),
(323645,35961,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... un circuit cool en Chine.'::text,'as'::text,'a'::text,'es'::text,'Je vais pas mentir, tu as un circuit cool en Chine.'::text),
(323648,35961,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, havalı bir Çin turun ...'::text,'var'::text,'var'::text,NULL::text,'Yalan yok, havalı bir Çin turun var.'::text),
(323649,35961,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ... egy menő kínai körutad.'::text,'van'::text,'van'::text,'vagy'::text,'Nem hazudok, van egy menő kínai körutad.'::text),
(323652,35962,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So cool, du machst drei ... in einer Woche.'::text,'Touren'::text,'Tour'::text,'Touren'::text,'So cool, du machst drei Touren in einer Woche.'::text),
(323656,35962,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Так круто, ти здійснюєш три ... за один тиждень.'::text,'подорожі'::text,'подорож'::text,'подорожі'::text,'Так круто, ти здійснюєш три подорожі за один тиждень.'::text),
(323655,35962,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué guay, haces tres ... en una semana.'::text,'circuitos'::text,'circuito'::text,'circuitos'::text,'Qué guay, haces tres circuitos en una semana.'::text),
(323654,35962,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop cool, tu fais trois ... en une semaine.'::text,'circuits'::text,'circuit'::text,'circuits'::text,'Trop cool, tu fais trois circuits en une semaine.'::text),
(323657,35962,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok havalı, bir haftada üç ... yapıyorsun.'::text,'tur'::text,'tur'::text,'turlar'::text,'Çok havalı, bir haftada üç tur yapıyorsun.'::text),
(323658,35962,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De menő, egy hét alatt három ... mész el.'::text,'körútra'::text,'körútra'::text,'körútra'::text,'De menő, egy hét alatt három körútra mész el.'::text),
(323661,35963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ich mag ... Reisevideo so sehr.'::text,'dein'::text,'ihr'::text,'sein'::text,'Ehrlich, ich mag dein Reisevideo so sehr.'::text),
(323665,35963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, мені так подобається ... відео з подорожі.'::text,'твоє'::text,'її'::text,'його'::text,'Чесно, мені так подобається твоє відео з подорожі.'::text),
(323664,35963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, me encanta ... vídeo del viaje.'::text,'tu'::text,'su'::text,'su'::text,'La verdad, me encanta tu vídeo del viaje.'::text),
(323663,35963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, j''adore ... vidéo de voyage.'::text,'ta'::text,'sa'::text,'sa'::text,'Franchement, j''adore ta vidéo de voyage.'::text),
(323666,35963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası ... tur videosunu çok seviyorum.'::text,'senin'::text,'onun'::text,'onun'::text,'Açıkçası senin tur videosunu çok seviyorum.'::text),
(323667,35963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, nagyon tetszik a ... az útról.'::text,'videód'::text,'videója'::text,'videója'::text,'Őszintén, nagyon tetszik a videód az útról.'::text),
(323679,35965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Reise hat ... Teile: die Mauer, den Fluss und den Markt.'::text,'drei'::text,'dritte'::text,'dritte'::text,'Ihre Reise hat drei Teile: die Mauer, den Fluss und den Markt.'::text),
(323683,35965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її подорож має ... частини: мур, річку й ринок.'::text,'три'::text,'треті'::text,'треті'::text,'Її подорож має три частини: мур, річку й ринок.'::text),
(323682,35965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su viaje tiene ... partes: la muralla, el río y el mercado.'::text,'tres'::text,'terceras'::text,'terceras'::text,'Su viaje tiene tres partes: la muralla, el río y el mercado.'::text),
(323681,35965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son voyage a ... parties : la muraille, le fleuve et le marché.'::text,'trois'::text,'troisièmes'::text,'troisièmes'::text,'Son voyage a trois parties : la muraille, le fleuve et le marché.'::text),
(323684,35965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun turunun ... bölümü var: sur, nehir ve pazar.'::text,'üç'::text,'üçüncü'::text,'üçüncü'::text,'Onun turunun üç bölümü var: sur, nehir ve pazar.'::text),
(323685,35965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ő körútja ... részből áll: a fal, a folyó és a piac.'::text,'három'::text,'harmadik'::text,'harmadik'::text,'Az ő körútja három részből áll: a fal, a folyó és a piac.'::text),
(323697,35967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf ihrer Reise gibt es ... Orte zu sehen.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Auf ihrer Reise gibt es viele Orte zu sehen.'::text),
(323701,35967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її подорожі ... місць, які варто побачити.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'У її подорожі багато місць, які варто побачити.'::text),
(323700,35967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En su viaje hay ... lugares que ver.'::text,'muchos'::text,'mucho'::text,'cualquier'::text,'En su viaje hay muchos lugares que ver.'::text),
(323699,35967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a ... endroits à voir pendant son voyage.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'n''importe quels'::text,'Il y a beaucoup d'' endroits à voir pendant son voyage.'::text),
(323702,35967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun turunda görülecek ... yer var.'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Onun turunda görülecek çok yer var.'::text),
(323703,35967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útján ... hely van, amit érdemes megnézni.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Az útján sok hely van, amit érdemes megnézni.'::text),
(323706,35968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf ihrer Rundreise durch China ... eine Bootsfahrt.'::text,'ist'::text,'sind'::text,'sein'::text,'Auf ihrer Rundreise durch China ist eine Bootsfahrt.'::text),
(323710,35968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її подорожі Китаєм ... прогулянка на човні.'::text,'є'::text,'є'::text,'бути'::text,'У її подорожі Китаєм є прогулянка на човні.'::text),
(323709,35968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En su viaje por China ... un paseo en barco.'::text,'hay'::text,'hay'::text,'hay'::text,'En su viaje por China hay un paseo en barco.'::text),
(323708,35968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant son circuit en Chine, ... une balade en bateau.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Pendant son circuit en Chine, il y a une balade en bateau.'::text),
(323711,35968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun Çin turunda bir tekne gezisi ...'::text,'var'::text,'var'::text,'olmak'::text,'Onun Çin turunda bir tekne gezisi var.'::text),
(323712,35968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kínai körútján ... egy hajókirándulás.'::text,'van'::text,'vannak'::text,'lenni'::text,'A kínai körútján van egy hajókirándulás.'::text),
(299487,33277,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ... hast du gelernt, so zu helfen?'::text,'wo'::text,'wer'::text,'was'::text,'Ehrlich, wo hast du gelernt, so zu helfen?'::text),
(299491,33277,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ... ти навчилася так допомагати?'::text,'де'::text,'хто'::text,'що'::text,'Чесно, де ти навчилася так допомагати?'::text),
(299490,33277,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ¿... aprendiste a ayudar así?'::text,'dónde'::text,'quién'::text,'qué'::text,'En serio, ¿dónde aprendiste a ayudar así?'::text),
(299489,33277,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, ... as-tu appris à aider comme ça ?'::text,'où'::text,'qui'::text,'que'::text,'Franchement, où as-tu appris à aider comme ça ?'::text),
(299492,33277,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, böyle yardım etmeyi ... öğrendin?'::text,'nerede'::text,'kim'::text,'ne'::text,'Açıkçası, böyle yardım etmeyi nerede öğrendin?'::text),
(299493,33277,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... tanultál meg így segíteni?'::text,'hol'::text,'ki'::text,'mi'::text,'Őszintén, hol tanultál meg így segíteni?'::text),
(299505,33279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise isst sie hier nur, aber gestern ... sie einem Mann beim Atmen.'::text,'half'::text,'hilft'::text,NULL::text,'Normalerweise isst sie hier nur, aber gestern half sie einem Mann beim Atmen.'::text),
(299509,33279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона тут просто їсть, але вчора ... чоловікові дихати.'::text,'допомогла'::text,'допомагає'::text,NULL::text,'Зазвичай вона тут просто їсть, але вчора допомогла чоловікові дихати.'::text),
(299508,33279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente solo come aquí, pero ayer ... a un hombre a respirar.'::text,'ayudó'::text,'ayuda'::text,NULL::text,'Normalmente solo come aquí, pero ayer ayudó a un hombre a respirar.'::text),
(299507,33279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle mange juste ici, mais hier elle ... un homme à respirer.'::text,'a aidé'::text,'aide'::text,NULL::text,'D''habitude, elle mange juste ici, mais hier elle a aidé un homme à respirer.'::text),
(299510,33279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde burada sadece yemek yer ama dün bir adamın nefes almasına ...'::text,'yardım etti'::text,'yardım eder'::text,NULL::text,'Genelde burada sadece yemek yer ama dün bir adamın nefes almasına yardım etti.'::text),
(299511,33279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában csak eszik itt, de tegnap ... egy férfinak levegőhöz jutni.'::text,'segített'::text,'segít'::text,NULL::text,'Általában csak eszik itt, de tegnap segített egy férfinak levegőhöz jutni.'::text),
(299514,33280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau, die Frau ... ihm mit einem Glas Wasser.'::text,'hilft'::text,'hilft'::text,'hilft'::text,'Schau, die Frau hilft ihm mit einem Glas Wasser.'::text),
(299518,33280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись, жінка ... йому склянкою води.'::text,'допомагає'::text,'допомагає'::text,'допомагає'::text,'Дивись, жінка допомагає йому склянкою води.'::text),
(299517,33280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira, la mujer lo ... con un vaso de agua.'::text,'está ayudando'::text,'ayuda'::text,'está ayudando'::text,'Mira, la mujer lo está ayudando con un vaso de agua.'::text),
(299516,33280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde, la femme ... avec un verre d''eau.'::text,'est en train de l''aider'::text,'l''aide'::text,'est en train de l''aider'::text,'Regarde, la femme est en train de l''aider avec un verre d''eau.'::text),
(299519,33280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak, kadın ona bir bardak suyla ...'::text,'yardım ediyor'::text,'yardım eder'::text,'yardım ediyor'::text,'Bak, kadın ona bir bardak suyla yardım ediyor.'::text),
(299520,33280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd, a nő egy pohár vízzel ... neki.'::text,'segít'::text,'segít'::text,'segít'::text,'Nézd, a nő egy pohár vízzel segít neki.'::text),
(299523,33281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er ihr nächste Woche beim Umzug ...'::text,'helfen wird'::text,'helfen wird'::text,'helfen wird'::text,'Mädel, er hat mir erzählt, dass er ihr nächste Woche beim Umzug helfen wird.'::text),
(299527,33281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що наступного тижня ... їй із переїздом.'::text,'збирається допомогти'::text,'збирається допомогти'::text,'збирається допомогти'::text,'Подруго, він сказав мені, що наступного тижня збирається допомогти їй із переїздом.'::text),
(299526,33281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que la ... a mudarse la semana que viene.'::text,'va a ayudar'::text,'va a ayudar'::text,'va a ayudar'::text,'Tía, me dijo que la va a ayudar a mudarse la semana que viene.'::text),
(299525,33281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''il ... l''aider à déménager la semaine prochaine.'::text,'va'::text,'va'::text,'va'::text,'Ma belle, il m''a dit qu''il va l''aider à déménager la semaine prochaine.'::text),
(299528,33281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dedi ki haftaya taşınmasına ...'::text,'yardım edecek'::text,'yardım edecek'::text,'yardım edecek'::text,'Kızım, bana dedi ki haftaya taşınmasına yardım edecek.'::text),
(299529,33281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy jövő héten ... neki a költözésben.'::text,'segíteni fog'::text,'segíteni fog'::text,'segíteni fog'::text,'Csajszi, azt mondta, hogy jövő héten segíteni fog neki a költözésben.'::text),
(299532,33282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat gesagt: Danke, ich ... dir jederzeit helfen.'::text,'werde'::text,'werde'::text,NULL::text,'Hör zu, er hat gesagt: Danke, ich werde dir jederzeit helfen.'::text),
(299536,33282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав: дякую, я ... тобі будь-коли.'::text,'допоможу'::text,'збираюся допомогти'::text,NULL::text,'Слухай, він сказав: дякую, я допоможу тобі будь-коли.'::text),
(299535,33282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo: gracias, te ... cuando quieras.'::text,'ayudaré'::text,'voy a ayudar'::text,NULL::text,'Oye, dijo: gracias, te ayudaré cuando quieras.'::text),
